IFL_DATA.register("products", [{"id":"current-account","name":"Current account","category":"Deposits","who":["ind","biz","corp"],"use":["save","service"],"need":"Safe keeping and payments, with money repayable on demand.","contracts":["qard"],"modeIds":["qard-hasan"],"topicIds":["t8.5.2","t14.3","t7.1"],"how":["The customer deposits money, which the bank holds as a loan (Qard) or Amanah.","The bank guarantees repayment on demand.","No return is paid, since any benefit on a loan would be Riba."],"numerical":{"title":"Why no profit on a current account","kind":"practice","given":[["Balance","50,000"],["Bank’s overall pool profit rate","8 %"]],"working":["The current account is a loan to the bank, not a Mudarabah investment.","The bank guarantees the 50,000, so the depositor bears no risk.","Any payment tied to the balance would be an increase on a loan."],"answer":"Return = 0; the 50,000 is guaranteed and repayable on demand."},"controls":["No return, gift or benefit stipulated on the balance.","Risks of current accounts stay with the bank and are not passed to investment accounts (p. 471)."],"risks":[["Withdrawal on demand","Liquidity management through Sukuk and interbank Mudarabah"]],"conventional":{"name":"Conventional current account","diff":["Both are usually non-remunerative; the Islamic account is explicitly a Qard, and its funds may be used only in Shari’ah-compliant business."]},"origin":["f1"]},{"id":"mudarabah-deposit","name":"Savings and term deposits (Mudarabah pool)","category":"Deposits","who":["ind","biz","inv"],"use":["save"],"need":"Earn a Halal return on savings with the flexibility of tenors.","contracts":["mudarabah","musharakah"],"modeIds":["mudarabah","musharakah"],"topicIds":["t8.5.2","t12.7.1","t14.3.1"],"how":["Depositors’ funds are pooled; each tenor category gets a disclosed weightage, which can change only at the start of a period.","The pool (as Rabbul-mal) and the bank (as Mudarib) share gross pool profit at the agreed ratio.","The pool’s share is distributed to depositors by weighted daily products.","A loss is shared by investment ratio, and the bank earns nothing as Mudarib."],"numerical":{"title":"Box 8.1: distributing pool profit","kind":"textbook","given":[["3-month deposits","$3,000 × 0.60"],["6-month deposits","$4,000 × 0.70"],["1-year deposits","$3,000 × 1.00"],["Profit on $10,000 for one month","$1,000"],["Mudarabah ratio","50 : 50"]],"working":["Bank as Mudarib: 1,000 × 50 % = $500; pool: $500.","Weighted amounts: 1,800 + 2,800 + 3,000 = 7,600.","3-month: 500 × 1,800 ÷ 7,600 = $119 (3.96 % monthly on its $3,000).","6-month: 500 × 2,800 ÷ 7,600 = $184 (4.60 %).","1-year: 500 × 3,000 ÷ 7,600 = $197 (6.56 %).","A $500 loss instead would be shared 150 / 200 / 150 by investment, ignoring weightages."],"answer":"Bank $500; depositors $119, $184 and $197 (Box 8.1, pp. 190–191)."},"controls":["No fixed return promised; projected rates are adjusted to actual results (p. 360).","Weightages disclosed; bigger balances of the same tenor should not be favoured (p. 359).","Head-office expenses are borne by the bank, not the pool (p. 331)."],"risks":[["Displaced commercial risk (pressure to match market rates)","Profit equalisation reserves with disclosure"],["Loss in the pool","Diversification across modes and sectors; reserves"]],"conventional":{"name":"Interest-bearing savings/term deposit","diff":["Conventional: principal plus fixed interest guaranteed. Islamic: variable return from actual pool profit; capital at the pool’s risk."]},"diagramId":"deposit-pool","calcId":"pool-weightage","origin":["f1"]},{"id":"wakalah-fund","name":"Investment fund on Wakalatul Istismar","category":"Deposits","who":["inv","ind"],"use":["save"],"need":"Professional management of funds for a known fee, with all results passing to investors.","contracts":["wakalah","islamic-funds"],"modeIds":["wakalah"],"topicIds":["t13.2.2","t8.5.2","t18.3.1"],"how":["The fee basis (lump sum or % of amount or NAV) is fixed before launch and disclosed in the prospectus.","The bank invests the fund as agent in compliant avenues.","Profit and loss belong entirely to investors; the bank earns only its fee."],"numerical":{"title":"Fee in a loss year","kind":"practice","given":[["NAV at year-end","200 million"],["Disclosed fee","2 % of NAV"],["Fund result","Loss of 5 million"]],"working":["Fee = 2 % × 200 m = 4 m.","The fee is independent of profit or loss.","Investors bear the 5 m loss and pay the 4 m fee."],"answer":"Manager earns 4 m; investors bear the loss (p. 349)."},"controls":["Fee method fixed before launch (p. 349).","Only Shari’ah-compliant investments; screening criteria applied."],"risks":[["Poor performance","Investor bears it — disclosure and screening"],["Fiduciary breach","Agent liable for negligence"]],"conventional":{"name":"Managed fund / guaranteed-return account","diff":["No guaranteed return; the manager’s income is a fee, not a spread."]},"origin":["f1"]},{"id":"auto-ijarah","name":"Car finance (Ijarah Muntahia-bi-Tamleek)","category":"Consumer finance","who":["ind"],"use":["asset"],"need":"Use of a car now with ownership at the end of the lease.","contracts":["ijarah","imbt","wad","wakalah"],"modeIds":["ijarah","ijarah-muntahia-bi-tamleek","wakalah"],"topicIds":["t11.5","t11.5.1","t11.4.5","t11.6"],"how":["Customer promises to lease and pays a refundable security deposit.","The bank buys the car (directly or through an agent) and owns it.","The Ijarah starts when the usable car is delivered; rent is fixed or floating with floor and cap.","The bank bears ownership risk and Takaful; the customer bears usage costs.","At the end the car passes by a separate sale or gift under a unilateral promise."],"numerical":{"title":"Box 11.3: car destroyed without negligence","kind":"textbook","given":[["Outstanding Ijarah investment + prepaid expenses","Rs.370,000"],["Takaful claim received","Rs.450,000"],["Security deposit","Rs.50,000"]],"working":["The lease ends and rent stops; the loss is the bank’s as owner.","The client gets back his deposit: Rs.50,000.","AAOIFI 8/8: pass the Takaful surplus to the client: 450,000 − 370,000 = Rs.80,000."],"answer":"Client receives Rs.130,000 (p. 303)."},"controls":["No sale clause inside the lease; ownership transfer only by separate promise (p. 290).","Rent only from delivery of a usable asset (p. 289).","Takaful at the lessor’s expense; late-payment amounts to charity (pp. 300–301)."],"risks":[["Customer refuses to lease after purchase","Binding promise plus Hamish Jiddiyah"],["Asset destroyed","Takaful"],["Inflation / rate risk","Floating rent with floor and cap"],["Careless use","Trust receipt; lessee liable for negligence"]],"conventional":{"name":"Hire-purchase / finance lease","diff":["Conventional: customer bears all risks, rent continues after theft, penalties taken as income, automatic transfer (Box 11.2).","Ijarah: bank bears ownership risk, rent stops if the car is lost, charity for late payment, separate sale or gift."]},"diagramId":"imbt","calcId":"ijarah-case","caseIds":["c-ijarah-car"],"origin":["f1"]},{"id":"home-dm","name":"Home finance (Diminishing Musharakah)","category":"Consumer finance","who":["ind"],"use":["home"],"need":"Buy a house with the bank as co-owner, paying rent and buying the bank’s share over time.","contracts":["diminishing-musharakah","ijarah","wad","shirkah"],"modeIds":["diminishing-musharakah","ijarah"],"topicIds":["t12.9.2","t12.8","t12.9"],"how":["Joint ownership (Shirkatulmilk) is created: e.g. bank 80 %, client 20 %.","The bank leases its undivided share to the client for rent.","The client buys the bank’s units under a unilateral promise, often on a pre-agreed schedule.","Rent falls as units are bought; title passes after the last unit."],"numerical":{"title":"Box 12.5: first and last instalments","kind":"textbook","given":[["House cost","1,000,000"],["Bank share","800,000 (80 %)"],["Tenure","120 monthly units"],["Rent rate","7 % p.a. on outstanding investment"]],"working":["Unit price = 800,000 ÷ 120 = 6,666.67.","Month 1 rent = 800,000 × 7 % ÷ 12 = 4,666.67 → payment 11,333.33.","Month 2 rent = 793,333.3 × 7 % ÷ 12 = 4,627.78 → 11,294.44.","Month 120 rent = 6,666.7 × 7 % ÷ 12 = 38.89 → 6,705.56."],"answer":"Payments fall from 11,333.33 to 6,705.56 (p. 342)."},"controls":["Three contracts kept separate and independently enforceable (p. 338).","Pre-agreed unit price allowed only in Shirkatulmilk (p. 338).","Floating rent needs a floor and cap (p. 343).","Construction or renovation: unit sales start one year after the last disbursement (p. 341)."],"risks":[["Client delays unit purchases","Rent continues on the bank’s units — less loss than Murabaha (p. 342)"],["Property damage","Takaful; costs shared by ownership"]],"conventional":{"name":"Interest-bearing mortgage","diff":["Mortgage: a loan secured on the house, with interest on the outstanding balance.","DM: joint ownership, rent for use of the bank’s share, sale of units; ownership risk is shared pro rata."]},"diagramId":"dm","calcId":"dm-schedule","caseIds":["c-dm-house","c-dm-construction"],"origin":["f1"]},{"id":"apartment-istisna-dm","name":"Apartment under construction (Istisna‘a + DM)","category":"Consumer finance","who":["ind"],"use":["home"],"need":"Finance a flat that a builder has not yet built.","contracts":["istisna","diminishing-musharakah","ijarah","wakalah"],"modeIds":["istisnaa","diminishing-musharakah","ijarah","wakalah"],"topicIds":["t10.11.10","t10.11","t12.9.2"],"how":["Client and bank form a Shirkatulmilk pool for the flat’s price.","They jointly sign an Istisna‘a with the builder and pay in instalments.","The client supervises construction as the bank’s agent.","On handover, the bank leases its share to the client, who buys units monthly (Diminishing Musharakah)."],"numerical":{"title":"Box 10.13: sharing the price","kind":"textbook","given":[["Apartment price","Rs.7 million"],["Client’s own funds","Rs.2 million"],["Bank financing","Rs.5 million over 10 years"]],"working":["Joint ownership: client 2/7 (28.6 %), bank 5/7 (71.4 %).","The Rs.7 m is paid to the builder in four instalments under Istisna‘a.","After handover the client pays rent on the bank’s Rs.5 m share and buys it in units over ten years."],"answer":"Bank owns 71.4 % at handover, falling to 0 as units are bought (pp. 274–275)."},"controls":["Istisna‘a price fixed and specifications clear.","DM rules after completion (separate lease and unit purchases)."],"risks":[["Builder delays","Shart-e-Jazai price reduction; performance bond"],["Quality","Specifications, supervision by agent"]],"conventional":{"name":"Construction-linked mortgage","diff":["No interest on stage payments; the bank co-owns the flat and earns rent only once it is usable."]},"diagramId":"istisna-housing","origin":["f1"]},{"id":"consumer-murabaha","name":"Consumer durables (Murabaha instalment sale)","category":"Consumer finance","who":["ind"],"use":["asset"],"need":"Buy a fridge, computer or motorbike and pay in instalments.","contracts":["murabaha","qabd","wad"],"modeIds":["murabaha"],"topicIds":["t9.6","t9.8","t9.9.4"],"how":["Customer requests the item and promises to buy.","The bank (or a subsidiary holding inventory) buys and owns the item.","The bank sells it at disclosed cost plus profit, payable in instalments.","The price is fixed; late payment may lead to a charity penalty, never a higher price."],"numerical":{"title":"Instalment price","kind":"practice","given":[["Cost to bank","60,000"],["Agreed profit","10 % flat for 12 months"]],"working":["Price = 60,000 × 1.10 = 66,000.","Instalment = 66,000 ÷ 12 = 5,500.","If month 8 is paid late, the price stays 66,000; any agreed penalty goes to charity."],"answer":"Price 66,000 in 12 instalments of 5,500."},"controls":["Bank owns and possesses before sale.","Mark-up from the date of sale, not disbursement (p. 365).","No rollover (p. 364)."],"risks":[["Default","Collateral; charity penalty as a deterrent"],["Item damaged before sale","Bank’s risk; Takaful"]],"conventional":{"name":"Consumer loan / credit purchase","diff":["The loan balance grows with interest on delay; the Murabaha price does not."]},"diagramId":"murabaha","calcId":"credit-price","origin":["f1"]},{"id":"islamic-card","name":"Islamic charge and credit cards","category":"Consumer finance","who":["ind"],"use":["cash","service"],"need":"Payments and short-term credit without interest.","contracts":["qard","wakalah"],"modeIds":["qard-hasan","wakalah"],"topicIds":["t14.4.7"],"how":["A charge card gives credit up to a limit, paid in full on the statement, with fixed fees.","Interest-free credit cards (e.g. EIB, KFH Al Tayseer) charge fixed service fees, not interest.","Merchant commission is allowed; cash withdrawals carry only a flat fee."],"numerical":{"title":"KFH Al Tayseer repayment","kind":"practice","given":[["Outstanding balance","9,000"],["Rule","One-third repaid each month; the rest rolls over without interest"]],"working":["Month 1 payment = 9,000 ÷ 3 = 3,000; carried 6,000.","No interest is added on the 6,000; the bank earns from the annual fee and merchant commissions."],"answer":"Pay 3,000; carry 6,000 interest-free (p. 383)."},"controls":["No interest condition, even if the holder intends to pay on time (OIC Fiqh Council 2000).","Flat cash-withdrawal fee, not linked to the amount (p. 381).","No prohibited privileges such as conventional life insurance."],"risks":[["Default","Salary account or lien (KFH); charity penalty"]],"conventional":{"name":"Revolving interest-bearing credit card","diff":["Conventional income is interest on the rolled-over balance; Islamic cards rely on fixed fees and merchant commission."]},"calcId":"late-payment","origin":["f1"]},{"id":"working-capital-murabaha","name":"Working capital: Murabaha to Purchase Orderer","category":"Trade & working capital","who":["biz"],"use":["wc"],"need":"Buy raw materials and inventory on deferred payment.","contracts":["murabaha","wakalah","wad","qabd","arbun"],"modeIds":["murabaha","wakalah"],"topicIds":["t9.8.3","t9.8","t14.4.1","t14.3.4"],"how":["Master Murabaha agreement and the client’s promise to buy (with Hamish Jiddiyah if needed).","A separate agency: the client buys the goods for the bank (the bank pays the supplier directly).","The client takes delivery as agent, and the goods are at the bank’s risk.","The client offers to buy and the bank accepts: cost plus profit, deferred.","The price is fixed; there is no rollover, and a new need means new goods and a new Murabaha."],"numerical":{"title":"Mark-up period","kind":"practice","given":[["Supplier paid on","1 March"],["Client’s offer accepted on","15 March"],["Cost","2,000,000"],["Profit","12 % p.a., 90 days from sale"]],"working":["Profit runs from the sale on 15 March, not from disbursement on 1 March.","Profit = 2,000,000 × 12 % × 90/365 = 59,178.","Price = 2,059,178, due 13 June."],"answer":"Murabaha price ≈ 2,059,178, with no mark-up for 1–15 March (p. 365)."},"controls":["Invoice date between the agency agreement and the offer (Box 9.1).","Supplier not the client’s sister concern (>50 %) (p. 365).","Goods must exist and be unused at the offer (p. 365).","DP note after the sale, or for principal only (p. 365)."],"risks":[["Client refuses to buy","Promise + Hamish Jiddiyah; actual loss only"],["Client already bought the goods (‘Inah)","Pay supplier directly; check invoices, gate passes, stock registers"],["Goods in transit lost","Bank’s risk; Takaful"],["Overdue","Undertaking to pay charity; collateral"]],"conventional":{"name":"Running finance / overdraft","diff":["Murabaha cannot replace a running facility: each drawing needs real goods and a separate sale (p. 223)."]},"diagramId":"mpo","calcId":"promise-breach","caseIds":["c-mpo-agent"],"origin":["f1"]},{"id":"import-murabaha","name":"Import finance: L/C Murabaha","category":"Trade & working capital","who":["biz"],"use":["trade"],"need":"Import goods through an L/C with deferred payment.","contracts":["murabaha","wakalah","musawamah"],"modeIds":["murabaha","wakalah","musawamah"],"topicIds":["t14.4.2","t9.8.3"],"how":["Master Murabaha + agency agreement before the deal with the foreign supplier (Box 9.2).","The bank opens the L/C; Takaful is arranged on the bank’s behalf, at its cost.","The documents arrive and the bank pays through its Nostro.","If the client pays at once: Musawamah or spot Murabaha at L/C cost + charges + Takaful.","If credit is needed: a sub-Murabaha, with profit from the Nostro debit to the settlement date."],"numerical":{"title":"Sub-Murabaha price","kind":"practice","given":[["L/C cost in rupees","6,000,000"],["Charges + Takaful","60,000"],["Profit rate","10 % p.a."],["Nostro debit to settlement","120 days"]],"working":["Cost = 6,060,000.","Profit = 6,060,000 × 10 % × 120/365 = 199,233.","Murabaha price = 6,259,233."],"answer":"≈ 6,259,233 payable after 120 days (TR Murabaha)."},"controls":["Agency before the import deal is finalised (Box 9.2).","The bank’s risk ends only on delivery to the customer.","In a shipping-guarantee case, only the cost part may be adjusted later (p. 373)."],"risks":[["Customer delays after sight payment","Agency lets the bank book a Murabaha rather than suffer a loss (p. 368)"]],"conventional":{"name":"Import loan / usance L/C with interest","diff":["Profit is on a sale of the goods, fixed once agreed, instead of interest accruing on a loan."]},"diagramId":"import-murabaha","origin":["f1"]},{"id":"export-bill-musawamah","name":"Export bill finance (Musawamah alternative to discounting)","category":"Trade & working capital","who":["biz"],"use":["trade","cash"],"need":"Cash now against an export bill without interest-based discounting.","contracts":["musawamah","wakalah","bai-sarf"],"modeIds":["musawamah","wakalah"],"topicIds":["t14.4.2"],"how":["The exporter holds a bill (e.g. US$100,000 due in 55 days).","The bank advances local currency as the exporter’s agent to buy goods the exporter needs.","The exporter buys the goods for the bank and declares possession; the bank then sells them to the exporter for the bill’s foreign-currency amount, payable on the bill date.","The bill proceeds settle the Musawamah price."],"numerical":{"title":"Section 14.4.2 figures","kind":"textbook","given":[["Bill","US$100,000 due in 55 days"],["Spot rate","Rs.57.75"],["Bank’s quoted rate","Rs.57.60"]],"working":["Funds disbursed for goods = 100,000 × 57.60 = Rs.5,760,000.","Goods sold to the exporter for US$100,000 payable on the bill date.","Bank’s margin in rupee terms if paid at a spot of 57.75 at maturity: 100,000 × (57.75 − 57.60) = Rs.15,000 (practice illustration)."],"answer":"Rs.5,760,000 now; US$100,000 on 25 February (p. 371)."},"controls":["Real goods bought and owned before the sale.","No discounting of the bill itself (a sale of debt)."],"risks":[["Bill not honoured","Recourse to the exporter as Musawamah buyer; L/C security"]],"conventional":{"name":"Bill discounting","diff":["Discounting sells a debt below face value — Riba. The Islamic route uses a real sale of goods."]},"diagramId":"musawamah-export","caseIds":["c-bill"],"origin":["f1"]},{"id":"export-istisna","name":"Pre-shipment export finance (Istisna‘a / Salam + agency)","category":"Trade & working capital","who":["biz"],"use":["trade","wc"],"need":"Funds to manufacture or procure goods for an export order.","contracts":["istisna","salam","wakalah"],"modeIds":["istisnaa","salam","wakalah"],"topicIds":["t10.11.10","t10.10","t14.4.1"],"how":["The exporter has an order (e.g. garments Rs.110 m).","The bank buys the goods from the exporter by Istisna‘a (made to order) or Salam (fungible goods), before any L/C for that sale exists.","The bank appoints the exporter its agent to export once the goods are the bank’s.","The importer’s L/C proceeds come to the bank."],"numerical":{"title":"Box 10.14: garment export","kind":"textbook","given":[["Istisna‘a price paid by bank","Rs.100 million"],["Export L/C value","Rs.110 million"],["Period","3 months"]],"working":["The bank buys the garments for Rs.100 m and takes delivery, bearing their risk.","It exports them through the client as agent and receives Rs.110 m under the L/C.","Gross margin = Rs.10 m, earned by owning and exporting goods."],"answer":"Bank’s gross margin Rs.10 m (pp. 275–276). Salam rice example: Rs.1.0 m paid, L/C Rs.1.1 m (Box 10.5)."},"controls":["If an L/C has already been opened in the client’s name, Istisna‘a is not possible (avoid ‘Inah) (p. 276).","The bank bears the goods’ risk after delivery; Takaful is its cost."],"risks":[["Order cancelled after delivery","Bank’s risk as owner — select sound buyers"],["Late or defective goods","Performance bond; Shart-e-Jazai in Istisna‘a"]],"conventional":{"name":"Pre-shipment export loan","diff":["The bank earns by buying and exporting goods, not by lending against the order."]},"diagramId":"istisna-export","origin":["f1"]},{"id":"salam-agri","name":"Agricultural finance (Salam with promise or Parallel Salam)","category":"Trade & working capital","who":["farm"],"use":["wc","cash"],"need":"Farmers’ pre-harvest funding; buyers’ price certainty.","contracts":["salam","wad","arbun"],"modeIds":["salam"],"topicIds":["t10.10","t10.10.1","t10.6"],"how":["The bank pays the full price at contract for specified crop quantity, quality, date and place.","It takes a buyer’s promise (with Hamish Jiddiyah), a Parallel Salam, or appoints the seller as agent to sell.","The bank takes delivery at maturity and then sells; it cannot resell before possession."],"numerical":{"title":"Box 10.4: wheat","kind":"textbook","given":[["Salam price paid 1 January","Rs.100 m for 5,000 tons"],["C’s promise to buy on 1 May","Rs.115 m"],["Hamish Jiddiyah","Rs.15 m"]],"working":["Gross margin if C buys = 115 − 100 = Rs.15 m.","If C refuses and the market pays Rs.108 m: actual loss = 115 − 108 = Rs.7 m, taken from the HJ; Rs.8 m refunded (practice extension)."],"answer":"Rs.15 m margin, earned by bearing delivery and price risk (pp. 259–260)."},"controls":["Full price at contract; no Salam in currencies or a specific field (pp. 244–245).","Parallel contract independent (p. 256).","Late-delivery penalty only to charity (p. 266)."],"risks":[["Seller fails to deliver","Security/pledge; buy from the market"],["Price falls","Parallel Salam or promise to buy"],["Holding costs","Recover in parallel pricing"]],"conventional":{"name":"Crop loan","diff":["The bank buys produce and bears price and delivery risk instead of lending at interest."]},"diagramId":"salam","calcId":"salam-profit","caseIds":["c-salam-wheat"],"origin":["f1"]},{"id":"salam-working-capital","name":"Working capital for manufacturers (Salam + selling agency)","category":"Trade & working capital","who":["biz"],"use":["wc","cash"],"need":"Cash for a sugar, cement or fertiliser producer against future output.","contracts":["salam","wakalah"],"modeIds":["salam","wakalah"],"topicIds":["t14.4.1","t10.10"],"how":["The bank buys future output by Salam, paying the full price now (it may take a charge on the mill’s assets).","A separate agency appoints the producer to sell the goods for the bank at a target price.","The bank takes delivery; the agent sells; proceeds go to the bank.","Any excess over the target may be the agent’s bonus if agreed; a shortfall is the bank’s loss."],"numerical":{"title":"Box 10.7: sugar","kind":"textbook","given":[["Salam price","Rs.19 per kg"],["Bank’s target sale price","Rs.20 per kg"],["Scenario A: agent sells at","Rs.21"],["Scenario B: market falls to","Rs.18"]],"working":["Target margin = 20 − 19 = Re.1 per kg.","A: sold at 21 — the extra Re.1 may be the agent’s fee if the bank agrees; the bank keeps Re.1.","B: sold at 18 — the bank loses Re.1 per kg; the agent does not guarantee the price."],"answer":"Bank’s result ranges from +Re.1 to −Re.1 per kg: real price risk (pp. 261–262)."},"controls":["Agency independent of the Salam.","The bank takes delivery before the agent sells."],"risks":[["Price risk","Borne by the bank — the price of genuine trade"]],"conventional":{"name":"Cash credit / running finance","diff":["Funds are provided against a purchase of real output, with the bank bearing price risk."]},"diagramId":"salam-sugar","origin":["f1"]},{"id":"running-musharakah","name":"Running Musharakah (working capital partnership)","category":"Trade & working capital","who":["biz"],"use":["wc"],"need":"Revolving working capital for a going business, sharing actual profit.","contracts":["musharakah"],"modeIds":["musharakah"],"topicIds":["t12.7.2","t14.4.1"],"how":["A Running Musharakah Account is opened with a limit.","Sale proceeds of finished goods are credited; drawings are debited.","The bank’s capital is the average utilised amount (daily product).","Operating profit is shared monthly or quarterly at the agreed ratio; loss by capital."],"numerical":{"title":"Quarterly profit share","kind":"practice","given":[["Average bank balance in the business","10 m"],["Client’s capital","30 m"],["Operating profit for the quarter","4 m"],["Agreed ratio (bank : client)","20 : 80"]],"working":["Bank = 4 m × 20 % = 0.8 m; client 3.2 m.","If the quarter made a loss of 2 m: bank bears 2 m × 10/40 = 0.5 m; client 1.5 m."],"answer":"Profit: bank 0.8 m. Loss: bank 0.5 m (by capital)."},"controls":["Only operating cash flows credited (p. 333).","Guarantees only against negligence or breach (p. 318).","Gross-profit sharing possible if the client bears indirect costs (p. 370)."],"risks":[["Under-reporting of profit","Documentation, audit rights, security against misconduct"]],"conventional":{"name":"Running finance with interest","diff":["The bank’s return depends on actual operating profit, not on the balance outstanding."]},"diagramId":"running-musharakah","calcId":"musharakah-pl","origin":["f1"]},{"id":"musharakah-trade","name":"Trade finance by Musharakah (single transaction)","category":"Trade & working capital","who":["biz"],"use":["trade"],"need":"Finance a single export or import deal and share its profit.","contracts":["musharakah","shirkah"],"modeIds":["musharakah"],"topicIds":["t12.7.2","t14.4.2"],"how":["The client prepares cost and profit estimates for a specific order.","The bank joins as partner for that transaction, profit shared at an agreed ratio.","Security covers only misconduct, breach or negligence.","The deal is liquidated when the proceeds arrive; profit is shared, and any loss by capital."],"numerical":{"title":"Box 12.2: import on partnership in creditworthiness","kind":"textbook","given":[["Usance L/C","Rs.10 million, 180 days"],["Clearing + installation","~30 + ~50 days"],["Customer payment","within 150 days of shipment"]],"working":["Proceeds (≤150 days) arrive before the L/C falls due (180 days), so there is no funding gap.","The partners buy on credit and sell for cash; profit is shared at the agreed ratio (Shirkatul Wujooh)."],"answer":"Profit shared as agreed; the bank settles the L/C at day 180 (pp. 334–335)."},"controls":["Wujooh accepted by Hanafis and Hanbalis; Shafi‘is reject it (pp. 310–311).","Loss follows the liability agreed at the start."],"risks":[["Buyer default","Partnership risk — careful client selection"]],"conventional":{"name":"Trade loan","diff":["The bank shares the deal’s profit and risk instead of charging interest for the period."]},"diagramId":"musharakah","caseIds":["c-wujooh-lc"],"origin":["f1"]},{"id":"corporate-ijarah","name":"Plant and machinery Ijarah / sale and lease-back","category":"Corporate & project","who":["biz","corp"],"use":["asset"],"need":"Fixed assets for a company, including assets it already owns.","contracts":["ijarah","imbt","wad","bai"],"modeIds":["ijarah","ijarah-muntahia-bi-tamleek"],"topicIds":["t11.5.1","t11.3.1","t11.6"],"how":["For new assets, the bank buys (via an agent if needed) and leases them.","For assets the client already owns, the bank buys them (sale) and then leases them back.","Transfer at the end is by separate sale or gift; for sale and lease-back, not within about a year."],"numerical":{"title":"Box 11.3: early purchase of ten cars","kind":"textbook","given":[["Client’s offer","Rs.400,000 per car × 10"],["Outstanding Ijarah investment","Rs.350,000 per car"],["Prepaid expenses incl. Takaful","Rs.20,000 per car"]],"working":["Liabilities per car = 350,000 + 20,000 = 370,000; ten cars = Rs.3.7 m.","Offer = Rs.4.0 m.","Profit = 4.0 − 3.7 = Rs.300,000 (Rs.30,000 per car), assuming the deposit is included in the offer."],"answer":"Accept: the offer covers liabilities and yields Rs.300,000 (p. 303)."},"controls":["Trucks bought from the market: direct lease; plant, looms and owned cars: sale and lease-back (Box 11.3).","No early retirement before one year in sale and lease-back.","Repairs caused by the client’s poor maintenance are borne by the client (Answer 2)."],"risks":[["Early termination","Promise to purchase on a price schedule in risky cases"],["Resale value","Lease only assets with a sufficient market"]],"conventional":{"name":"Term loan / finance lease","diff":["The bank owns the asset and bears ownership risk; rent is for use, not interest on principal."]},"diagramId":"ijarah","calcId":"ijarah-case","origin":["f1"]},{"id":"project-istisna","name":"Project finance: Istisna‘a with Parallel Istisna‘a","category":"Corporate & project","who":["corp"],"use":["project"],"need":"Build roads, plants or buildings with deferred payment.","contracts":["istisna","wakalah"],"modeIds":["istisnaa","wakalah"],"topicIds":["t10.11.7","t10.11.10","t14.4.3"],"how":["The bank sells the asset to the customer by Istisna‘a (price payable over time).","It buys the asset from a contractor by a separate Parallel Istisna‘a (paid in stages).","It appoints the customer or a consultant to supervise.","On completion the contractor delivers to the bank and the bank delivers to the customer."],"numerical":{"title":"Box 10.16: government road","kind":"textbook","given":[["Istisna‘a price to government","Rs.1,200 m over 10 years"],["Parallel Istisna‘a with contractor","Rs.1,000 m in four equal instalments"]],"working":["Instalments to the contractor = 1,000 ÷ 4 = Rs.250 m each.","Bank’s gross margin = 1,200 − 1,000 = Rs.200 m, received over ten years (tolls assigned; shortfall paid by the government).","Box 10.15 building: builder pays Rs.120 m, contractor gets Rs.100 m → Rs.20 m margin."],"answer":"Rs.200 m margin on the road; Rs.20 m on the flats (pp. 276–277)."},"controls":["Parallel delivery date not earlier than the original (p. 267).","The two contracts are independent; the parallel contract is only with a third party.","Price fixed; not priced on a Murabaha cost-plus basis (p. 265)."],"risks":[["Contractor delay","Shart-e-Jazai"],["Quality","Supplier guarantee; supervision"],["Bank does not own the materials","Security from the manufacturer"]],"conventional":{"name":"Construction loan","diff":["The bank earns the difference between two sale prices, bearing delivery risk."]},"diagramId":"parallel-istisna","calcId":"parallel-istisna","origin":["f1"]},{"id":"musharakah-tfc","name":"Musharakah term finance certificates","category":"Corporate & project","who":["corp"],"use":["raise"],"need":"Long-term corporate funding with profit-based returns.","contracts":["musharakah","sukuk"],"modeIds":["musharakah","sukuk"],"topicIds":["t12.7.3"],"how":["The company issues certificates representing a share in the profit of the business or project.","Returns follow tiered formulas on actual operating profit.","Principal is redeemed over the term."],"numerical":{"title":"Box 12.3: Sitara TFCs (Level I)","kind":"textbook","given":[["Issue","Rs.360 million, five years (June 2002)"],["Level I","12 % of the first Rs.100 m of operating profit"],["Level II","2 % of each further Rs.100 m; ¼ to a Takaful reserve"]],"working":["If operating profit is Rs.100 m, Level I = 12 m to TFC holders.","Actual returns reported were about 15–24 %, depending on profit."],"answer":"Returns track operating profit rather than a fixed coupon (Box 12.3)."},"controls":["No fixed return guaranteed by the issuer."],"risks":[["Profit shortfall","Holders share the downside"]],"conventional":{"name":"Interest-bearing TFC / bond","diff":["Return from a profit formula, not a coupon."]},"calcId":"sitara-tfc","caseIds":["c-sitara"],"origin":["f1"]},{"id":"syndication","name":"Syndicated Ijarah–Istisna‘a (oil terminal)","category":"Corporate & project","who":["corp"],"use":["project"],"need":"Very large projects financed by several banks.","contracts":["istisna","ijarah","wad","wakalah"],"modeIds":["istisnaa","ijarah","wakalah"],"topicIds":["t14.4.3"],"how":["The operator gives a binding unilateral promise to lease.","The consortium signs an Istisna‘a with a contractor.","The operator supervises construction as agent.","On completion the consortium leases the terminal to the operator."],"numerical":{"title":"Sharing the rent","kind":"practice","given":[["Terminal cost","Rs.10 billion"],["Bank A share","30 %"],["Annual rent","Rs.1.1 billion"]],"working":["Bank A owns 30 % and receives 30 % × 1.1 bn = Rs.330 m a year.","It bears 30 % of ownership risk and costs."],"answer":"Rs.330 m a year to Bank A, with 30 % of ownership risk."},"controls":["Ijarah executed only after the asset exists and is owned (p. 374)."],"risks":[["Construction delay","Shart-e-Jazai in the Istisna‘a"]],"conventional":{"name":"Syndicated loan","diff":["Banks co-own the asset and earn rent, instead of lending at a spread."]},"diagramId":"ijarah-istisna-project","origin":["f1"]},{"id":"ijarah-sukuk","name":"Sovereign / corporate Ijarah Sukuk","category":"Sukuk","who":["corp","inv"],"use":["raise","save"],"need":"Raise large funds against real assets; give investors tradable, quasi-fixed income.","contracts":["sukuk","ijarah","wad","bai"],"modeIds":["sukuk","ijarah"],"topicIds":["t15.3.5.b","t15.4.cases","t15.3.7"],"how":["An SPV buys an asset from the originator (a true sale).","The SPV issues Sukuk representing pro rata ownership of the asset.","The SPV leases the asset to the originator; rent flows to holders.","At maturity the originator repurchases under a separate undertaking."],"numerical":{"title":"Box 15.6: Pakistan’s sovereign Sukuk","kind":"textbook","given":[["Issue","US$600 m, 5 years (January 2005)"],["Pricing","6-month LIBOR + 220 bps"],["Orders","US$1.2 bn from 82 accounts"]],"working":["If 6-m LIBOR = 4.80 %, rent rate = 7.00 % p.a.","Semi-annual rent ≈ 600 m × 7.00 % ÷ 2 = US$21 m.","Oversubscription = 1,200 ÷ 600 = 2×."],"answer":"≈ US$21 m per half-year at a 4.80 % LIBOR (pp. 413–414)."},"controls":["Sukuk must represent ownership, not just rent receivables (p. 402).","No issuer guarantee of face value except for tort or negligence (AAOIFI).","Repurchase at least a year after the sale (p. 397)."],"risks":[["Asset destroyed","Holders bear it as owners — Takaful"],["Pre-fixed return concerns","Book’s critique, Section 15.3.7"]],"conventional":{"name":"Government bond","diff":["A bond is a debt; Ijarah Sukuk are ownership of an asset earning rent, tradable at market price."]},"diagramId":"sukuk","calcId":"sukuk-trade","caseIds":["c-pak-sukuk","c-wapda","c-nakheel"],"origin":["f1"]},{"id":"liquidity-tools","name":"Liquidity management (interbank Mudarabah, Sukuk, Commodity Murabaha)","category":"Treasury & capital markets","who":["bank"],"use":["cash","save"],"need":"Place surplus funds or cover shortfalls without interest.","contracts":["money-market","mudarabah","sukuk","tawarruq","salam"],"modeIds":["mudarabah","sukuk","tawarruq","salam"],"topicIds":["t14.4.4","t8.8.5","t13.3.1"],"how":["Interbank Mudarabah: the deficit bank shares its general profit at a negotiated ratio.","Sukuk bought at par and sold outright when cash is needed (not a repo).","Invite investment in a pool of Murabaha and Ijarah assets (Murabaha receivables < 50 %).","Commodity Murabaha (Tawarruq) only as a last resort, under Shari’ah-board supervision."],"numerical":{"title":"Interbank Mudarabah return","kind":"practice","given":[["Placement","100 m for 30 days"],["Investee bank’s gross profit rate","9 % p.a."],["Ratio (investor : investee)","70 : 30"]],"working":["Gross profit on the placement = 100 m × 9 % × 30/365 = 739,726.","Investor’s share = 70 % = 517,808."],"answer":"≈ 517,808 — known only when the investee’s profit is known (p. 206)."},"controls":["No fixed return on Mudarabah placements.","Tawarruq never sold back to the seller; goods must move (p. 350)."],"risks":[["Return uncertainty","Diversify instruments"],["Paper-only Tawarruq","Board supervision; limited use"]],"conventional":{"name":"Call money and repo","diff":["No interest-bearing lending between banks; returns come from profit sharing or asset sales."]},"diagramId":"tawarruq","calcId":"tawarruq-check","origin":["f1"]},{"id":"fx-forward-cover","name":"Foreign exchange: spot dealing and forward cover by promise","category":"Treasury & capital markets","who":["biz","bank"],"use":["protect","trade"],"need":"Currency for trade and remittances, and protection against rate moves.","contracts":["bai-sarf","wad","arbun"],"modeIds":[],"topicIds":["t14.4.5","t8.8.7"],"how":["Spot FX with settlement within two days at the deal-date rate.","For genuine documented trade needs, a unilateral promise to sell or buy currency at a pre-agreed rate on a future date.","The actual exchange takes place simultaneously on that date; no cover fee; earnest money may be taken."],"numerical":{"title":"Importer’s forward cover","kind":"practice","given":[["Need","US$500,000 in 90 days"],["Promised rate","Rs.60.20"],["Earnest money","Rs.1,000,000"],["Spot at maturity if the client defaults","Rs.59.80"]],"working":["At maturity the client pays 500,000 × 60.20 = Rs.30,100,000 and receives the dollars.","If he defaults, the bank sells the dollars at 59.80: loss = 500,000 × 0.40 = Rs.200,000, taken from the earnest money; Rs.800,000 refunded."],"answer":"Actual loss only: Rs.200,000 (p. 377)."},"controls":["Genuine documented need — no speculators (p. 377).","A promise, not a forward sale; no cover fee."],"risks":[["Client default","Earnest money covers actual loss"]],"conventional":{"name":"FX forward contract","diff":["A conventional forward is a sale for future delivery on both sides; here there is only a unilateral promise and a spot exchange later."]},"calcId":"fx-settlement","origin":["f1"]},{"id":"iers","name":"Export refinance from the central bank (SBP IERS)","category":"Treasury & capital markets","who":["biz","bank"],"use":["trade"],"need":"Priority-sector refinance without interest.","contracts":["musharakah"],"modeIds":["musharakah"],"topicIds":["t14.4.6"],"how":["The Islamic bank forms a Musharakah pool of at least ten blue-chip exporters’ financings.","SBP invests in the pool and shares its actual profit on daily products.","Profit above the conventional EFS rate goes to a Takaful fund held by SBP.","Losses are shared by investment, SBP’s share met first from the Takaful fund."],"numerical":{"title":"Excess profit","kind":"practice","given":[["SBP’s average investment","Rs.1,000 m"],["SBP’s share of pool profit","9 % p.a."],["EFS rate","7 % p.a."]],"working":["SBP’s profit share = Rs.90 m.","At the EFS rate = Rs.70 m.","Excess Rs.20 m goes to the Takaful fund (within 7 days of determination)."],"answer":"Rs.20 m to the Takaful fund (p. 378)."},"controls":["Only transactions approved by the bank’s Shari’ah board.","Actual, not fixed, profit."],"risks":[["Pool loss","Takaful fund absorbs SBP’s share first"]],"conventional":{"name":"Export finance scheme (EFS)","diff":["The central bank earns a share of actual pool profit instead of a fixed refinance rate."]},"diagramId":"iers","origin":["f1"]},{"id":"lc-lg","name":"Letters of credit and guarantees","category":"Services & Takaful","who":["biz","corp"],"use":["service","trade"],"need":"Payment assurance in trade; performance and bid guarantees.","contracts":["wakalah","security"],"modeIds":["wakalah"],"topicIds":["t14.6","t5.8"],"how":["L/C: a banking service charged as a fee that is not time-related; it may vary with L/C type and effort.","L/G: guarantee itself is gratuitous; fees cover related services and expenses.","If a guarantee is called, the bank recovers only the principal."],"numerical":{"title":"Guarantee called","kind":"practice","given":[["Guarantee amount","Rs.5 m"],["Called and paid by the bank","Rs.5 m"],["Client repays after","60 days"]],"working":["The bank recovers Rs.5 m only.","No charge for the 60 days (that would be Riba); the service fee agreed at issue is unaffected."],"answer":"Recover Rs.5 m; no time-based charge (p. 385)."},"controls":["No time-based L/C or L/G fee (pp. 384–385).","Standby L/Cs are treated as guarantees."],"risks":[["Called guarantee not reimbursed","Collateral; margin"]],"conventional":{"name":"Conventional L/C and L/G commission","diff":["Conventional pricing often varies with time outstanding; Islamic fees reflect service and effort."]},"origin":["f1"]},{"id":"jualah-services","name":"Service products on Ju‘alah (debt recovery, brokerage)","category":"Services & Takaful","who":["ind","biz","corp"],"use":["service"],"need":"Pay for a result whose effort cannot be specified in advance.","contracts":["jualah"],"modeIds":["juaalah"],"topicIds":["t13.4.6","t13.4.5"],"how":["Reward fixed as an amount or a share of the result (e.g. % of debts recovered).","No result, no reward; the offeror pays a market wage if he revokes after work begins.","The bank may sub-contract by Parallel Ju‘alah."],"numerical":{"title":"Recovery reward","kind":"practice","given":[["Recovered","3,000,000"],["Reward","4 %"],["Advance paid on account","50,000"]],"working":["Reward = 120,000.","Less advance on account 50,000 → 70,000 payable."],"answer":"70,000 still payable (pp. 352–355)."},"controls":["Task must not be the worker’s existing legal duty (p. 352)."],"risks":[["No recovery","Offeror pays nothing"]],"conventional":{"name":"Collection agency on retainer","diff":["Payment depends on the result, not on time spent."]},"diagramId":"jualah","calcId":"jualah-reward","caseIds":["c-jualah-recovery"],"origin":["f1"]},{"id":"takaful","name":"Takaful (general and family)","category":"Services & Takaful","who":["ind","biz","corp","farm"],"use":["protect"],"need":"Cover against loss without Riba, Gharar and Maisir.","contracts":["takaful","waqf","wakalah","mudarabah"],"modeIds":["takaful","wakalah","mudarabah"],"topicIds":["t16.4.1","t16.4","t16.5"],"how":["Participants donate (Tabarru‘) to a Waqf fund created by shareholders.","The operator charges a Wakalah fee and invests the fund as Mudarib.","Claims are paid from the fund; the underwriting surplus belongs to participants.","Family Takaful adds a savings part returned with profit at maturity."],"numerical":{"title":"Year-end result","kind":"practice","given":[["Donations","20 m"],["Wakalah fee","25 %"],["Claims and re-Takaful","9 m"],["Investment profit","2 m, shared fund 60 : operator 40"]],"working":["Fee = 5 m.","Underwriting surplus = 20 − 5 − 9 = 6 m → participants.","Investment profit: fund 1.2 m, operator 0.8 m."],"answer":"Surplus 6 m to participants; operator 5.8 m (fee + share) (Box 16.1 method)."},"controls":["Operator does not take the underwriting surplus as a risk-taker (p. 426).","Deficits met from reserves, then Qard from shareholders (p. 427).","Reduce the fee, not the risk premium, for large clients."],"risks":[["Deficit","Reserves; Qard al Hasan; re-Takaful"]],"conventional":{"name":"Conventional insurance","diff":["Risk sold to an insurer that keeps the surplus; Takaful shares risk among participants, who own the surplus."]},"diagramId":"takaful","calcId":"takaful-waqf","caseIds":["c-takaful-fund"],"origin":["f1"]},{"id":"special-investment","name":"Special investment deposits and individual portfolios","category":"Deposits","who":["inv","corp"],"use":["save"],"need":"A large investor wants funds managed separately from the general pool, with a return tied to specific investments.","contracts":["mudarabah","wakalah"],"modeIds":["mudarabah","wakalah"],"topicIds":["t8.5.3","t8.5.2","t13.2.2"],"how":["The investor places funds for a special purpose or an individual portfolio, outside the general deposit pool (Box 8.2).","The bank manages the funds either as Mudarib, for an agreed share of actual profit, or as investment agent (Wakalatul Istismar), for a fee fixed in advance.","The funds go only into the agreed Shari’ah-compliant assets, such as Ijarah, Murabaha or Sukuk.","The investor’s return comes only from those assets; there is no guaranteed rate."],"numerical":{"title":"Mudarabah or agency basis for the same result","kind":"practice","given":[["Portfolio","50,000,000"],["Net profit for the year","4,000,000"],["Option A: Mudarabah ratio (investor : bank)","80 : 20"],["Option B: Wakalah fee","1 % of the portfolio"]],"working":["A: the bank takes 4,000,000 × 20 % = 800,000; the investor gets 3,200,000 (6.4 %).","B: the fee is 50,000,000 × 1 % = 500,000; the investor gets 3,500,000 (7.0 %).","In a loss year the Mudarib earns nothing, but the agent still earns its fee; in both cases the investor bears the loss unless the bank was negligent."],"answer":"Investor 3.2 m under Mudarabah; 3.5 m under Wakalah in this year."},"controls":["Fee basis or profit ratio fixed before the funds are invested (p. 349).","No guarantee of capital or return by the manager.","The portfolio is ring-fenced from the general pool, so its results are not mixed with the general pool’s."],"risks":[["Concentration in a few assets","Diversification limits agreed in the mandate"],["Manager’s negligence","Manager liable for negligence or breach of the mandate"]],"conventional":{"name":"Special-rate term deposit / discretionary portfolio","diff":["Conventional: negotiated fixed interest, or a portfolio that may hold interest-bearing assets.","Islamic: return only from the specific compliant assets; the manager earns a profit share or a pre-set fee."]},"origin":["f1"]},{"id":"interbank-mudarabah","name":"Islamic interbank money market (Mudarabah interbank investment)","category":"Treasury & capital markets","who":["bank"],"use":["cash","save"],"need":"A bank with surplus funds for a day to a year places them with a bank that is short of liquidity.","contracts":["money-market","mudarabah","liquidity"],"modeIds":["mudarabah"],"topicIds":["t8.8.5","t14.4.4"],"how":["A surplus bank (investor) places funds with a deficit bank (investee) on Mudarabah, from overnight to 12 months (Malaysia’s MII, IIMM from January 1994).","The profit-sharing ratio is negotiated; the return is based on the investee bank’s gross profit rate before distribution on one-year investments.","The actual return is known only at the end of the period.","Principal is repaid at maturity with the investor’s share of profit. Elsewhere, placements are often treated like ordinary deposits and paid by weightage and daily product."],"numerical":{"title":"Return on an MII placement","kind":"practice","given":[["Amount placed","100,000,000"],["Period","30 days"],["Investee bank’s gross profit rate (1-year investments)","6.0 % p.a."],["Profit-sharing ratio (investor : investee)","70 : 30"]],"working":["Gross profit attributable = 100,000,000 × 6 % × 30/365 = 493,151.","Investor’s share = 493,151 × 70 % = 345,205.","Effective return to the investor = 6 % × 70 % = 4.2 % p.a."],"answer":"About 345,205 for the month, known only when the investee’s profit rate is crystallised."},"controls":["No guaranteed rate; the ratio is agreed and the return crystallises at the end (p. 206).","Bank Negara’s minimum benchmark from February 1996 (government investment issue rate + 0.5 %) only filters participants; it does not guarantee a return.","Placements must be used only in Shari’ah-compliant business."],"risks":[["Investee bank’s profit falls","Choose sound counterparties; the benchmark screens weak banks"],["Liquidity mismatch","Laddered tenors from overnight to 12 months"]],"conventional":{"name":"Interbank call money / placements","diff":["Conventional: fixed interest agreed upfront. Islamic MII: a share of the investee’s actual profit, known only at maturity."]},"diagramId":"interbank-mii","origin":["f1"]},{"id":"house-construction-dm","name":"House construction, renovation and balance transfer (Diminishing Musharakah)","category":"Consumer finance","who":["ind"],"use":["home"],"need":"Build a house on land the client already owns, renovate a house, or move an interest-based mortgage to an Islamic bank.","contracts":["diminishing-musharakah","shirkah","ijarah","wad"],"modeIds":["diminishing-musharakah","ijarah"],"topicIds":["t12.9.2","t12.8","t12.2.1"],"how":["The bank buys units of the client’s land (or house) to create joint ownership (Shirkatulmilk): a sale and lease-back.","For construction, the purchase price is released in instalments and the client builds the house with it.","Once the house is habitable the bank leases its share; for a renovation, rent starts from the first month because the client already lives there.","The bank starts selling its units back one year after the last instalment, to avoid ‘Inah; rent then falls with each unit bought.","A balance transfer facility (BTF) uses the same method to pay off an interest-based mortgage."],"numerical":{"title":"Box 12.4: house on the customer’s land","kind":"textbook","given":[["Land value","Drs 1,000,000 (10 units of 100,000)"],["Finance needed","Drs 800,000"],["Disbursement","Four equal instalments"]],"working":["The bank buys 8 of the 10 units: ownership becomes bank 80 %, client 20 %.","Each instalment = 800,000 ÷ 4 = Drs 200,000, used by the client to build.","For up to a year after completion the client pays only rent on the bank’s 80 %, so rent does not fall.","Unit sales begin one year after the last instalment; each purchase reduces the rent."],"answer":"Bank 80 % co-owner; four instalments of Drs 200,000; unit buy-back starts a year after the last instalment (p. 341)."},"controls":["A one-year gap before the bank sells units back, to avoid buy-back (Bai‘ al ‘Inah) (p. 341).","No rent on a house that is not yet habitable, except in a renovation, where the client already has its use.","Floating rent must have a floor and cap (p. 343)."],"risks":[["Construction delay","Client acts as the bank’s agent to supervise; staged disbursement"],["Client stops buying units","Rent continues on the bank’s units; equitable mortgage"],["Property value falls","Bank shares ownership risk; valuation at purchase of extra units"]],"conventional":{"name":"Construction loan / home-improvement loan / mortgage refinance","diff":["Conventional: a loan with interest from the first disbursement. Islamic: co-ownership, rent only on the bank’s share once it can be used, and units bought back at agreed prices."]},"diagramId":"dm-construction","calcId":"dm-schedule","caseIds":["c-dm-construction"],"origin":["f1"]},{"id":"personal-tawarruq","name":"Personal cash finance (Salam if possible, otherwise Tawarruq)","category":"Consumer finance","who":["ind"],"use":["cash"],"need":"An individual needs cash rather than a specific asset.","contracts":["tawarruq","murabaha","salam"],"modeIds":["tawarruq","murabaha","salam"],"topicIds":["t13.3","t8.5.3"],"how":["Box 8.2 suggests Salam where the client has a product to sell forward, and otherwise Tawarruq.","The bank buys a commodity with a brisk market and takes possession.","It sells the commodity to the client on deferred payment by a separate contract.","The client sells it to a third party (not the bank) for spot cash."],"numerical":{"title":"Cost of cash through Tawarruq","kind":"practice","given":[["Bank’s purchase price of the commodity","100,000"],["Deferred sale price to the client (12 months)","112,000"],["Client’s spot sale price to a third party","99,500"]],"working":["The client receives 99,500 in cash now.","The client owes the bank 112,000 in 12 months.","Effective cost of the cash = 112,000 − 99,500 = 12,500, i.e. about 12.6 % of the cash received."],"answer":"Cash 99,500 now; debt 112,000; cost about 12.6 % for the year."},"controls":["Sale back to the bank, directly or through an agent, makes it ‘Inah and invalid (p. 350).","The bank must own and possess the commodity; stipulating that the bank will sell it for the client invalidates the deal.","Scholars quoted by the author advise against Tawarruq for individual consumers; Qard al Hasan is preferable (pp. 350–351)."],"risks":[["Paper transactions through commodity exchanges","Real, identifiable goods with transfer of ownership"],["Reputation risk from overuse","Shari’ah board limits and monitoring"]],"conventional":{"name":"Personal loan","diff":["Conventional: cash lent at interest. Tawarruq: two real sales with a third-party buyer; a grey area that the book advises limiting."]},"diagramId":"tawarruq","calcId":"tawarruq-check","caseIds":["c-tawarruq-check"],"origin":["f1"]},{"id":"farm-machinery-ijarah","name":"Tractors, tubewells, farm machinery and fishing boats","category":"Agriculture","who":["farm"],"use":["asset"],"need":"A farmer or fisherman needs durable equipment paid for over several seasons.","contracts":["imbt","ijarah","salam","murabaha"],"modeIds":["ijarah-muntahia-bi-tamleek","ijarah","salam","murabaha"],"topicIds":["t8.5.3","t11.5","t11.5.1"],"how":["Box 8.2 lists Ijarah Muntahia-bi-Tamleek, Salam and Murabaha for tubewells, tractors, trailers, farm machinery and transport, including fishing boats.","Under IMBT the bank buys and owns the tractor, leases it, and transfers it at the end by a separate sale or gift.","Under Murabaha the bank sells the machine on instalments at a fixed price.","Under Salam the farmer can pay with a future crop delivered to the bank, which the bank then sells."],"numerical":{"title":"Tractor on IMBT with harvest-season rent","kind":"practice","given":[["Tractor cost","2,400,000"],["Tenor","4 years, rent twice a year after each harvest"],["Rent basis","Recover cost plus 10 % p.a. on the outstanding amount"]],"working":["Capital recovered each half-year = 2,400,000 ÷ 8 = 300,000.","First rent = 300,000 + 2,400,000 × 10 % ÷ 2 = 420,000.","Second rent = 300,000 + 2,100,000 × 5 % = 405,000, falling by 15,000 each half-year."],"answer":"Rents fall from 420,000 to 315,000; the tractor is gifted or sold after the last rent."},"controls":["Rent only after delivery of a usable asset; the bank bears ownership risk and Takaful.","Payment dates may follow the crop cycle; the rent for the first term must be known.","A Salam alternative requires the full price paid in advance for crop of known specification."],"risks":[["Crop failure delays rent","Takaful; rescheduling without increasing the debt"],["Machine destroyed","Lessor’s Takaful; rent stops"]],"conventional":{"name":"Agricultural term loan","diff":["Conventional: interest-bearing loan secured on the machine. Islamic: the bank owns the machine and bears its risk until transfer."]},"diagramId":"imbt","calcId":"ijarah-case","origin":["f1"]},{"id":"livestock-finance","name":"Livestock, dairy, poultry and farm inputs","category":"Agriculture","who":["farm"],"use":["asset","wc"],"need":"Buy seed, fertiliser, pesticides, plough or milk cattle, or poultry stock.","contracts":["murabaha","salam","wakalah"],"modeIds":["murabaha","salam","wakalah"],"topicIds":["t8.5.3","t10.10","t9.3"],"how":["For inputs and pesticides, and for cattle, dairy and poultry, Box 8.2 lists Murabaha and Salam.","Murabaha: the bank buys the animals or inputs, takes possession (directly or through an agent), and sells them to the farmer at cost plus a disclosed profit.","Salam: the bank pays the full price now for milk, eggs or crop to be delivered later, and sells them through Parallel Salam or a promise to buy."],"numerical":{"title":"Dairy cattle on Murabaha vs milk on Salam","kind":"practice","given":[["Ten cows bought by the bank","1,500,000"],["Murabaha profit","12 % for 12 months"],["Alternative Salam","Pay 1,500,000 now for 30,000 litres of milk over 12 months"],["Promised resale price of the milk","Rs.56 per litre"]],"working":["Murabaha price = 1,500,000 × 1.12 = 1,680,000; monthly instalment 140,000.","Salam: the bank’s sale of the milk = 30,000 × 56 = 1,680,000.","Both give the bank 180,000 gross, but under Salam the bank bears delivery and price risk on the milk until it sells."],"answer":"Murabaha: 1,680,000 in 12 instalments. Salam: 30,000 litres worth 1,680,000 at the promised price."},"controls":["The bank must own the animals before selling them in Murabaha; no sale of livestock not yet owned.","Salam goods must be fungible, precisely specified and deliverable on a fixed date; full advance payment.","No roll-over that increases the Murabaha price."],"risks":[["Animal death or disease","Takaful; the bank’s risk ends at delivery under Murabaha"],["Milk price falls (Salam)","Promise to buy with Hamish Jiddiyah; Parallel Salam"]],"conventional":{"name":"Crop and livestock loans","diff":["Conventional: interest on a cash loan. Islamic: the bank trades the animals or the produce itself."]},"diagramId":"salam","calcId":"salam-profit","origin":["f1"]},{"id":"farm-structures-dm","name":"Farm sheds, storage and fencing (Diminishing Musharakah or rent-sharing)","category":"Agriculture","who":["farm"],"use":["asset"],"need":"Build storage, animal sheds or fencing on the farm and pay for it over time.","contracts":["diminishing-musharakah","shirkah","ijarah"],"modeIds":["diminishing-musharakah","ijarah"],"topicIds":["t8.5.3","t12.8","t12.9"],"how":["Box 8.2 names Diminishing Musharakah or rent-sharing for storage and other farm construction.","The bank and the farmer co-own the structure in proportion to their funding.","The farmer pays rent for the bank’s share (or shares the rental income if the store is let to others).","The farmer buys the bank’s units over time until the structure is fully his."],"numerical":{"title":"Cold store with shared rental income","kind":"practice","given":[["Store cost","5,000,000 (bank 3,000,000, farmer 2,000,000)"],["Store let to other farmers","Rent 900,000 a year"],["Farmer buys","10 % of the store each year from the bank"]],"working":["Year 1 ownership: bank 60 %, farmer 40% → rent split 540,000 / 360,000.","After buying 10 % at the end of year 1 (500,000 at the agreed unit price), the bank owns 50 %.","Year 2 rent split 450,000 / 450,000; the bank’s share keeps falling."],"answer":"Bank’s rent share falls from 540,000 to 450,000 as its ownership falls from 60 % to 50 %."},"controls":["Rent is charged only on the bank’s share and only once the structure is usable.","The unit-purchase promise is unilateral and separate from the partnership agreement.","Loss of the structure is shared by ownership."],"risks":[["Structure damaged","Shared by ownership; Takaful"],["Farmer’s income is seasonal","Unit purchases timed to harvests"]],"conventional":{"name":"Farm development loan","diff":["Conventional: loan repaid with interest regardless of use. Islamic: joint ownership with rent or income shared by ownership."]},"diagramId":"dm","calcId":"dm-schedule","origin":["f1"]},{"id":"orchard-land","name":"Land development, orchards, nurseries and forestry","category":"Agriculture","who":["farm"],"use":["project","wc"],"need":"Develop farmland or finance an orchard, nursery or forest before it yields.","contracts":["ijarah","salam","shirkah"],"modeIds":["ijarah","salam"],"topicIds":["t8.5.3","t11.4","t10.10"],"how":["Box 8.2 lists operating Ijarah and Salam for land development, and Salam and Musaqat for orchards, nurseries and forestry.","Operating Ijarah: the bank owns levelling or irrigation equipment and hires it out, taking it back after each lease.","Salam: the bank pays now for fruit or timber of known specification to be delivered at harvest.","Musaqat is one of the classical agricultural partnerships, with Muzara‘a, in which parties share the produce (p. 122); AAOIFI’s Musaqah Sukuk fund projects for irrigating fruit-bearing trees, and Mugharasah Sukuk fund planting gardens (p. 396)."],"numerical":{"title":"Salam for a mango crop","kind":"practice","given":[["Salam price paid now","Rs.3,000,000 for 50 tons of Grade-A mangoes"],["Delivery","After the harvest in July"],["Parallel Salam sale","50 tons at Rs.66,000 per ton"]],"working":["Bank’s cost per ton = 3,000,000 ÷ 50 = Rs.60,000.","Parallel Salam proceeds = 50 × 66,000 = Rs.3,300,000.","Gross margin = Rs.300,000 (10 %), earned by bearing the risk on the mangoes; the two Salam contracts are independent."],"answer":"Margin Rs.300,000 if both Salam contracts are performed."},"controls":["Salam is not allowed for trees, land or the produce of “this field”, which may yield nothing; it must be for goods of a described kind and quality (p. 244).","Operating Ijarah: the lessor keeps ownership, re-leases and bears obsolescence.","The two Salam contracts must be independent of each other."],"risks":[["Poor harvest","Specification not tied to a single orchard; Takaful"],["Equipment idle between leases (operating Ijarah)","Pool of lessees; seasonal pricing"]],"conventional":{"name":"Orchard or land-development loan","diff":["Conventional: loan against land. Islamic: the bank buys produce in advance or owns and hires out the equipment."]},"origin":["f1"]},{"id":"post-shipment-qard","name":"Post-shipment export finance: Qard against the bill plus a collection fee","category":"Trade & working capital","who":["biz"],"use":["trade","cash"],"need":"An exporter has shipped goods and needs the bill amount before the importer pays.","contracts":["qard","wakalah","bai-sarf","wad"],"modeIds":["qard-hasan","wakalah"],"topicIds":["t14.4.2","t8.5.3"],"how":["Box 8.2 and Section 14.4.2: in place of bill discounting, the bank gives an interest-free loan (Qard) in local currency at the spot rate.","The bank takes over the bill for collection as the exporter’s agent and charges a service fee that is related to the amount, not to time.","The bills are negotiated at face value.","A separate promise to sell the foreign exchange in future lets the bank earn the exchange-rate differential; Murabaha can be added if funds are needed for the next consignment."],"numerical":{"title":"Discounting vs Qard plus a collection fee","kind":"practice","given":[["Export bill","Rs.5,000,000 (converted at spot)"],["Days to maturity","90 (or 30)"],["Conventional discount rate","12 % p.a."],["Islamic collection fee","0.25 % of the bill, flat"]],"working":["Discounting deducts 5,000,000 × 12 % × 90/365 = 147,945 (49,315 for 30 days): the charge grows with time, which is Riba.","Qard: the exporter receives 5,000,000 at face value.","Collection fee = 5,000,000 × 0.25 % = 12,500 whether the bill takes 30 or 90 days."],"answer":"Exporter gets 5,000,000 now and pays a flat 12,500 fee; the fee does not depend on time."},"controls":["Face-value negotiation; no deduction that increases with time (p. 371).","The fee must reflect the collection service, not the length of the loan.","The FX leg is a promise, not a forward sale; exchange takes place at settlement."],"risks":[["Bill dishonoured","Recourse to the exporter for the Qard principal only"],["Bank earns little on the Qard","FX differential via promise; Murabaha for the next consignment"]],"conventional":{"name":"Export bill discounting / negotiation","diff":["Conventional: bill bought at a discount that is interest for the period. Islamic: interest-free loan plus a time-independent collection fee."]},"diagramId":"post-shipment","caseIds":["c-bill"],"origin":["f1"]},{"id":"export-consignment-purchase","name":"Cash purchase of a ready export consignment","category":"Trade & working capital","who":["biz"],"use":["trade","cash"],"need":"An exporter’s consignment is ready under an accepted L/C, but he needs liquidity within days.","contracts":["bai","wakalah","qabd"],"modeIds":["wakalah"],"topicIds":["t14.4.2"],"how":["Section 14.4.2 (Abdul’s case): the bank buys the ready goods from the exporter for cash.","The L/C is assigned in the bank’s favour.","The bank appoints the exporter its agent to ship the goods on its behalf.","The bank earns its margin through the purchase price and receives the bill proceeds at maturity (90 days)."],"numerical":{"title":"Abdul’s $100 m consignment (margin assumed)","kind":"practice","given":[["L/C value","US$100 m, 90 days (from the book)"],["Bank’s cash purchase price","US$98.6 m (practice figure)"]],"working":["Abdul receives US$98.6 m now.","The bank ships as owner through Abdul as agent and receives US$100 m under the L/C after 90 days.","Bank’s margin = US$1.4 m, earned by owning the goods and bearing their risk from purchase to shipment."],"answer":"Bank’s margin US$1.4 m; Abdul gets liquidity without interest-based discounting."},"controls":["A genuine sale of existing goods, with the bank taking ownership and risk.","The L/C proceeds are the bank’s as the new owner; this is not a discount of Abdul’s receivable.","The agency to ship is a separate contract."],"risks":[["Goods damaged before shipment","Bank’s risk as owner; Takaful"],["L/C discrepancy","Exporter as agent prepares documents; indemnity for negligence"]],"conventional":{"name":"Negotiation of export documents at a discount","diff":["Conventional: money now for more money later. Islamic: the bank buys goods and sells them to the importer."]},"origin":["f1"]},{"id":"musharakah-export","name":"Export finance by Musharakah or Mudarabah (single consignment)","category":"Trade & working capital","who":["biz"],"use":["trade","wc"],"need":"An exporter with a firm order at a known price needs funds to manufacture or buy the goods.","contracts":["musharakah","mudarabah","wakalah"],"modeIds":["musharakah","mudarabah","wakalah"],"topicIds":["t12.7.2","t12.7.3","t14.4.2"],"how":["The exporter gets an order at a known price and estimates cost and profit (Box 12.2).","The bank finances the manufacture or procurement on Shirkah; profit is shared at an agreed percentage.","The goods are readied for shipment under joint ownership; the exporter prepares documents strictly per the L/C.","Export proceeds are distributed by the agreed ratio; the bank bears loss from any cause other than the exporter’s negligence."],"numerical":{"title":"Consignment Musharakah","kind":"practice","given":[["Order value","12,000,000"],["Cost of goods","10,000,000 (bank 8,000,000, exporter 2,000,000)"],["Agreed profit ratio (bank : exporter)","50 : 50 (exporter manages)"]],"working":["Profit = 12,000,000 − 10,000,000 = 2,000,000; each gets 1,000,000.","The bank recovers its 8,000,000 plus 1,000,000.","If the goods sold for only 9,000,000, the loss of 1,000,000 is shared 80 : 20 by capital: bank 800,000, exporter 200,000."],"answer":"Profit: 1,000,000 each. Loss of 1,000,000: bank 800,000, exporter 200,000."},"controls":["Security only against negligence, misconduct or breach, not against loss (p. 335).","Loss follows capital; profit ratio agreed in advance.","A single, identifiable transaction keeps monitoring simple."],"risks":[["Exporter under-reports profit","Documented consignment; L/C proceeds flow through the bank"],["Exporter fails to perform","Indemnity for failure to honour his commitment (p. 332)"]],"conventional":{"name":"Pre-shipment export loan","diff":["Conventional: fixed interest whatever the export earns. Islamic: the bank shares the consignment’s actual profit or loss."]},"diagramId":"musharakah","calcId":"musharakah-pl","origin":["f1"]},{"id":"commodity-operations","name":"Government commodity operations (e.g. wheat procurement) by Murabaha","category":"Trade & working capital","who":["corp"],"use":["wc"],"need":"A provincial government must buy the harvest at a support price without interest-based borrowing.","contracts":["murabaha","wakalah","musharakah"],"modeIds":["murabaha","wakalah","musharakah"],"topicIds":["t14.4.2"],"how":["Conventionally, banks lend to provincial governments at interest to pay farmers at procurement centres.","Islamic banks may form a syndicate or a company that buys the wheat from farmers or suppliers.","Food departments and trading entities act as the company’s agents.","The company sells the wheat to the provincial government at cost plus profit; it holds real inventory and tangible assets (p. 372)."],"numerical":{"title":"Wheat syndicate Murabaha","kind":"practice","given":[["Wheat bought","100,000 tons at Rs.25,000 per ton support price"],["Agency and storage costs","Rs.50 m"],["Murabaha profit","8 % on total cost, deferred 6 months"]],"working":["Cost = 100,000 × 25,000 + 50 m = Rs.2,550 m.","Profit = 2,550 m × 8 % = Rs.204 m.","Murabaha price to the province = Rs.2,754 m, payable in 6 months."],"answer":"Rs.2,754 m, fixed at the sale and not increased for late payment."},"controls":["The syndicate must own the wheat (through agents) before selling it.","Cost is disclosed; the price is fixed once the sale is made.","Separate purchase and sale; agents are liable only for negligence."],"risks":[["Wheat damaged in storage","Syndicate’s risk as owner; Takaful"],["Government delays payment","Debt cannot grow; sovereign undertaking"]],"conventional":{"name":"Commodity financing loan to government","diff":["Conventional: interest on cash credit. Islamic: the banks trade the wheat themselves."]},"diagramId":"murabaha","calcId":"credit-price","origin":["f1"]},{"id":"shipping-guarantee-murabaha","name":"Shipping guarantee / delivery order with sub-Murabaha","category":"Trade & working capital","who":["biz"],"use":["trade","service"],"need":"Imported goods arrive by air before the shipping documents, and the importer wants them released.","contracts":["murabaha","security","wakalah"],"modeIds":["murabaha","wakalah"],"topicIds":["t14.4.2","t9.3"],"how":["The customer asks the bank for a shipping guarantee or delivery order (p. 373).","The bank takes a margin, e.g. 110 %, and executes a sub-Murabaha at that day’s exchange rate; the sale price is fixed.","When the documents arrive, if the final cost is higher or lower, the bank settles the difference.","Only the cost portion is adjusted; the profit portion is not."],"numerical":{"title":"Settling the cost difference","kind":"practice","given":[["Estimated cost at sub-Murabaha","10,000,000"],["Profit agreed","300,000"],["Final cost when documents arrive","10,150,000"],["Margin held","110 % of cost"]],"working":["Murabaha price booked = 10,300,000.","The cost rose by 150,000, so the customer pays 150,000 more: the price becomes 10,450,000.","Profit stays 300,000; it is not recalculated on the higher cost."],"answer":"Customer pays an extra 150,000; the profit is unchanged at 300,000."},"controls":["Adjustment is permissible because Murabaha is cost-plus and it was stipulated in advance (p. 373).","Only cost is adjusted, never the profit portion.","The bank’s risk ends only when the goods are delivered to the customer."],"risks":[["Customer disputes the final cost","Stipulated adjustment clause; documents as evidence"],["Goods released before documents","110 % margin; guarantee to the shipping line"]],"conventional":{"name":"Shipping guarantee with interest-bearing import loan","diff":["Conventional: interest runs until the loan is repaid. Islamic: a fixed Murabaha price, with only the cost difference settled."]},"diagramId":"import-murabaha","origin":["f1"]},{"id":"istijrar-supply","name":"Supply finance by Istijrar (running supply agreement)","category":"Trade & working capital","who":["biz"],"use":["wc"],"need":"A retailer or manufacturer takes regular deliveries of the same goods and wants one master arrangement.","contracts":["istijrar","murabaha","salam"],"modeIds":["bai-al-istijrar","murabaha","salam"],"topicIds":["t13.5"],"how":["A master agreement sets the supply of a product from time to time, e.g. monthly, at an agreed price and payment mode (p. 355).","The price may be fixed in advance, with each consignment, or after all deliveries.","Scholars relax the fixing and payment of price for everyday trade where there is no Gharar, e.g. bread paid for monthly.","If the arrangement is Murabaha, each consignment needs a separate offer and acceptance on the client’s requisition."],"numerical":{"title":"Monthly Murabaha consignments under a master agreement","kind":"practice","given":[["Consignments","Weekly, 2,000 kg of cotton yarn"],["Bank’s cost","Rs.400 per kg"],["Profit","3 % per consignment, payable at month-end"]],"working":["Each consignment costs 2,000 × 400 = Rs.800,000.","Murabaha price per consignment = 800,000 × 1.03 = Rs.824,000, agreed by a separate offer and acceptance.","Four consignments in the month → Rs.3,296,000 due at month-end."],"answer":"Rs.3,296,000 for the month: four separate Murabaha sales under one master agreement."},"controls":["Istijrar is not a separate mode; each sale must be valid on its own terms.","Murabaha: ownership and possession before each sale, with a separate offer and acceptance.","No Gharar in quantity, quality or price basis."],"risks":[["Client stops ordering","Promise to purchase for each requisition"],["Price changes between consignments","Price fixed per consignment"]],"conventional":{"name":"Running finance / cash credit line","diff":["Conventional: a revolving loan with interest on the daily balance. Istijrar: a series of real sales under one master agreement."]},"origin":["f1"]},{"id":"dm-business","name":"Diminishing Musharakah in trade or business","category":"Corporate & project","who":["biz"],"use":["raise"],"need":"An entrepreneur wants a financier as partner now, and to buy the financier out gradually.","contracts":["diminishing-musharakah","musharakah","wad"],"modeIds":["diminishing-musharakah","musharakah"],"topicIds":["t12.9.1","t12.8"],"how":["Two partners start a business (e.g. 40 : 60); one partner’s units are periodically sold to the other until he exits.","Because the business is run for profit and no lease is involved, the unit price cannot be fixed in the promise.","Each unit is sold at a valuation made when it is sold, by experts agreed in advance; sale by fresh offer and acceptance.","The promise to sell can bind only the financier; the entrepreneur buys voluntarily at the prevailing or agreed price (OIC Fiqh Academy, IRTI)."],"numerical":{"title":"Buying out the bank at valuation","kind":"practice","given":[["Bank’s share","60 % of the business"],["Bank sells","15 % of the business each year"],["Valuation at end of year 1","20,000,000"],["Valuation at end of year 2","24,000,000"]],"working":["Year 1 purchase = 15 % × 20,000,000 = 3,000,000; bank’s share falls to 45 %.","Year 2 purchase = 15 % × 24,000,000 = 3,600,000; bank’s share falls to 30 %.","The price follows the value, so the bank shares in growth or decline until it exits."],"answer":"3,000,000 in year 1 and 3,600,000 in year 2; the bank’s share falls 60 % → 45 % → 30 %."},"controls":["No fixed buy-back price for a trading business (p. 340).","The binding promise to sell is on the financier only.","Profit shared by ratio, loss by capital, throughout."],"risks":[["Business value falls","Shared by ownership; the bank sells at a lower valuation"],["Valuation disputes","Expert valuers agreed when the promise is signed"]],"conventional":{"name":"Term loan / private equity with a guaranteed buy-back","diff":["Conventional: a fixed exit price or interest. Islamic: a market valuation at each sale; the bank bears business risk until it exits."]},"calcId":"musharakah-pl","origin":["f1"]},{"id":"project-musharakah","name":"Project finance by Musharakah and Istisna‘a (cement plant)","category":"Corporate & project","who":["corp"],"use":["project"],"need":"Finance a plant that does not yet exist, where Ijarah cannot start until it is built.","contracts":["musharakah","istisna","wakalah","ijarah"],"modeIds":["musharakah","istisnaa","wakalah","ijarah"],"topicIds":["t14.4.3","t12.7.2"],"how":["The bank joins the project by Musharakah (Mudarabah if it provides all the funds; a combination if one party manages).","It signs an Istisna‘a with an industrial concern to build the plant and appoints the client as agent to supervise erection.","Once the plant runs, the bank takes rent on its ownership share and recovers its principal by selling units to the client at market price.","Alternatively the partners share the production profit (pp. 373–374). The bank may also stipulate a right to convert its outstanding investment into shares on an agreed formula (p. 333)."],"numerical":{"title":"Rent on the bank’s share, then units at market price","kind":"practice","given":[["Plant cost","Rs.4,000 m (bank Rs.2,400 m = 60 %)"],["Annual rent for the whole plant","Rs.500 m"],["Bank sells","10 % of the plant in year 3 at a market value of Rs.4,400 m"]],"working":["Bank’s rent in years 1–2 = 60 % × 500 m = Rs.300 m a year.","Year 3 sale = 10 % × 4,400 m = Rs.440 m, at market value, not cost.","Bank’s share falls to 50 %; rent from year 4 = Rs.250 m."],"answer":"Rent Rs.300 m a year, then Rs.440 m received for 10 %; rent falls to Rs.250 m."},"controls":["No rent before the plant can be used.","Units sold at market price, not a guaranteed amount (p. 374).","The client supervising as agent is liable only for negligence."],"risks":[["Construction delay or failure","Istisna‘a with a specialist; the contractor is liable for specification"],["Plant performs poorly","Shared as owners; feasibility appraisal and monitoring"]],"conventional":{"name":"Project term loan","diff":["Conventional: interest from disbursement. Islamic: partnership and manufacture first, then rent and unit sales."]},"diagramId":"parallel-istisna","origin":["f1"]},{"id":"operating-lease","name":"Operating lease of aircraft, ships and specialised machinery","category":"Corporate & project","who":["corp","biz"],"use":["asset"],"need":"A user needs a costly asset for a period without buying it.","contracts":["ijarah"],"modeIds":["ijarah"],"topicIds":["t11.4","t11.3.5","t11.3.2"],"how":["The owner gives possession of the asset for rent and keeps ownership; the asset returns to the lessor when the lease ends (p. 288).","This is fully compatible with Shari’ah, subject to the rules of Ijarah.","It suits high-cost, long-lead assets such as aircraft and ships.","It is rarely used by banks; NBFIs keep a stock of specialised machinery and re-lease it, bearing the risk of obsolescence, recession or falling demand."],"numerical":{"title":"Re-leasing an aircraft","kind":"practice","given":[["Aircraft cost to the lessor","US$60 m"],["Lease 1","5 years at US$0.6 m a month"],["Idle period before lease 2","4 months"],["Lease 2","5 years at US$0.5 m a month"]],"working":["Lease 1 rent = 60 × 0.6 = US$36 m.","Lease 2 rent = 60 × 0.5 = US$30 m.","Total rent = US$66 m over 10 years and 4 months; the idle months and the lower second rent are the lessor’s risk."],"answer":"US$66 m rent over two leases; the aircraft stays the lessor’s throughout."},"controls":["The lessor bears ownership costs and risk; the lessee pays operating costs.","Rent for each term known at the start; later terms can be benchmarked with floor and cap.","No promise to transfer ownership is needed."],"risks":[["Obsolescence and residual value","Lessor’s pricing; diversified fleet"],["Idle periods","Re-leasing capability"]],"conventional":{"name":"Conventional operating lease","diff":["Very close in substance; the Islamic version removes interest-based penalties and keeps major maintenance and Takaful with the lessor."]},"diagramId":"ijarah","calcId":"floating-rent","origin":["f1"]},{"id":"underwriting","name":"Underwriting of share and Sukuk issues","category":"Funds & investment banking","who":["corp"],"use":["raise","service"],"need":"A company issuing shares wants a commitment that the whole issue will be taken up.","contracts":["wakalah","security","shirkah"],"modeIds":["wakalah"],"topicIds":["t14.6","t8.8.2","t8.7"],"how":["The underwriter commits to take up any part of the issue left unsubscribed.","Its fee is only for arranging procurement of the capital and for services such as feasibility studies or marketing (OIC Fiqh Council, 1992).","A take-up commission for the commitment itself is not permissible.","Any shares the underwriter takes are at the offer price, like every other subscriber."],"numerical":{"title":"Fee and take-up on a Rs.500 m issue","kind":"practice","given":[["Issue size","Rs.500 m at Rs.10 per share"],["Underwritten","Rs.200 m"],["Public subscription","Rs.440 m"],["Arrangement and marketing fee","0.4 % of the underwritten amount"]],"working":["Unsubscribed = 500 − 440 = Rs.60 m: the underwriter buys 6 m shares at Rs.10, the offer price.","Fee = 0.4 % × 200 m = Rs.0.8 m, for arranging and marketing only.","A conventional take-up commission (e.g. 1 % of the 60 m) cannot be charged."],"answer":"Underwriter subscribes Rs.60 m at the offer price and earns a Rs.0.8 m service fee."},"controls":["No compensation for the commitment itself (pp. 203, 384).","Take-up at the offer price, without a discount.","Only the issues of Shari’ah-compliant companies may be underwritten."],"risks":[["Heavy take-up in a weak market","Syndicate of underwriters; due diligence"],["Shares fall after listing","Underwriter holds them as an ordinary shareholder"]],"conventional":{"name":"Conventional underwriting","diff":["Conventional: take-up commission for the guarantee and shares often at a discount. Islamic: fee for services only; take-up at the offer price."]},"origin":["f1"]},{"id":"investment-banking","name":"Venture capital, corporate finance and advisory (Islamic investment banking)","category":"Funds & investment banking","who":["corp","biz"],"use":["raise","service"],"need":"Companies need equity, restructuring or M&A support from a Shari’ah-compliant house.","contracts":["musharakah","mudarabah","wakalah","screening"],"modeIds":["musharakah","mudarabah","wakalah"],"topicIds":["t8.7","t8.8.2","t12.6"],"how":["Islamic investment banks provide venture capital to small, medium and large companies, excluding prohibited sectors (p. 199).","Corporate finance: IPOs, offers for sale, rights issues, private placements, strategic reviews, restructurings, acquisitions, divestments, mergers and joint ventures.","They manage portfolios, unit trusts and mutual funds, and arrange syndicated finance.","Income comes from partnership profits on venture capital and from fees for advisory work."],"numerical":{"title":"Venture capital by Musharakah with exit at valuation","kind":"practice","given":[["Investment","Rs.50 m for 25 % of a start-up"],["Profit ratio agreed","25 % to the bank (equal to its capital share)"],["Year-3 profit","Rs.40 m"],["Exit value of the 25 % in year 5","Rs.120 m"]],"working":["Year-3 profit share = 25 % × 40 m = Rs.10 m.","Exit gain = 120 − 50 = Rs.70 m, realised by selling the shares at their valuation.","Had the start-up failed, the bank would have lost its capital as a partner."],"answer":"Rs.10 m profit share in year 3 and a Rs.70 m gain on exit; no guaranteed return."},"controls":["No investment in prohibited businesses; equity screening applies.","No preference shares that guarantee capital or profit (OIC Fiqh Council, p. 203).","Advisory fees are for work done; no interest-bearing bridge loans."],"risks":[["Start-up failure","Portfolio diversification; staged investment"],["Exit difficulty","Promise by founders to buy at market value"]],"conventional":{"name":"Conventional investment banking","diff":["Same services; the Islamic house excludes interest-based instruments and prohibited sectors, and takes real equity risk."]},"origin":["f1"]},{"id":"equity-fund","name":"Islamic equity funds (income, growth, aggressive, balanced)","category":"Funds & investment banking","who":["inv","ind"],"use":["save"],"need":"Savers want diversified exposure to Shari’ah-compliant shares.","contracts":["islamic-funds","screening","mudarabah","wakalah"],"modeIds":["mudarabah","wakalah"],"topicIds":["t8.8.1","t8.8.2","t14.3.4"],"how":["Investors pool money; the manager buys screened shares and distributes dividends and capital gains pro rata (p. 201).","The manager works on Mudarabah (a share of realised profit) or agency (a fee, e.g. a % of NAV).","Four types: regular income, capital gain, aggressive and balanced funds (p. 202).","The fund purifies income: e.g. Al Meezan’s charity rate (non-compliant income ÷ gross revenue) × dividend received goes to a charity account (p. 203)."],"numerical":{"title":"Screening and purifying one holding","kind":"practice","given":[["Company’s debt ÷ 12-month average market cap","28 %"],["Cash + interest-bearing securities ÷ market cap","21 %"],["Receivables ÷ market cap","36 %"],["Non-compliant income ÷ gross revenue","2 %"],["Dividend received by the fund","Rs.1,500,000"]],"working":["DJIM tests: debt 28 % < 33 % ✓; cash 21 % < 33 % ✓; receivables 36 % ≥ 33 % ✗ — the stock fails the DJIM screen.","Had it passed, charity = 2 % × 1,500,000 = Rs.30,000.","Non-permissible income 2 % is within Al Meezan’s 5 % tolerance, but a single failed ratio excludes the stock under DJIM."],"answer":"Excluded under DJIM (receivables 36 %); the purification amount would have been Rs.30,000."},"controls":["Neither principal nor return guaranteed (p. 202).","Screening: Halal business; debt, cash and receivables each < 33 % of average market cap (DJIM).","Purification is the investor’s duty; the manager excludes prohibited income in a fund (p. 203)."],"risks":[["Market risk","Borne by investors; diversification"],["A stock drifts out of compliance","Periodic re-screening and divestment"]],"conventional":{"name":"Conventional equity mutual fund","diff":["Conventional: any stock and interest on cash. Islamic: screened stocks only, purified income, and no guarantees."]},"diagramId":"islamic-fund","calcId":"equity-screen","origin":["f1"]},{"id":"ijarah-fund","name":"Ijarah (leasing) funds","category":"Funds & investment banking","who":["inv"],"use":["save"],"need":"Investors want a stable, asset-backed return from leased assets.","contracts":["islamic-funds","ijarah","sukuk","mudarabah"],"modeIds":["ijarah","sukuk","mudarabah"],"topicIds":["t8.8.1","t15.3.5.b","t11.5.3"],"how":["Fund proceeds buy assets such as buildings, vehicles or equipment, which are leased to users (pp. 201, 401).","The fund manager or SPV keeps ownership; rents are distributed pro rata to subscribers.","Units are tradable at market prices, since they represent real assets; a buyer steps into the seller’s share of ownership.","Most jurists hold that such a fund cannot be a Mudarabah, as Mudarabah is limited to trade; the Hanbali view, preferred by most contemporary scholars, allows it (p. 401)."],"numerical":{"title":"Distributing rent after ownership costs","kind":"practice","given":[["Fund size","Rs.200 m (2,000,000 units)"],["Annual rent from lessees","Rs.22 m"],["Major repairs and Takaful (owner’s costs)","Rs.3 m"],["Manager’s fee","1 % of fund size"]],"working":["Net rent = 22 − 3 − 2 = Rs.17 m.","Per unit = 17 m ÷ 2,000,000 = Rs.8.50 (8.5 %).","Owner’s costs vary, which is why Ijarah Sukuk and funds are quasi-fixed, not fixed, return (p. 403)."],"answer":"Rs.8.50 per unit (8.5 %), after owner’s costs and the fee."},"controls":["Owner bears major maintenance and destruction; rent stops if the asset is lost.","Units tradable only while they represent real assets.","Rent for each term known; later terms benchmarked with limits."],"risks":[["Lessee default","Security deposits; diversified lessees"],["Asset destroyed","Takaful; ownership risk shared pro rata"]],"conventional":{"name":"Bond or fixed-income fund","diff":["Conventional: interest-bearing debt. Ijarah fund: rent from owned assets, net of the owner’s costs."]},"diagramId":"sukuk","calcId":"sukuk-trade","origin":["f1"]},{"id":"commodity-fund","name":"Commodity funds","category":"Funds & investment banking","who":["inv"],"use":["save"],"need":"Investors want returns from trading real commodities.","contracts":["islamic-funds","bai","salam","qabd"],"modeIds":["salam"],"topicIds":["t8.8.1","t8.8.6"],"how":["Subscriptions buy commodities for resale; profits on sale are distributed to subscribers (p. 201).","Every purchase and sale must meet the rules of sale: ownership, possession and no short selling.","The fund may buy forward by Salam, paying the full price in advance; it may not sell goods it does not yet own.","Units are tradable while the fund holds mainly goods rather than cash or receivables."],"numerical":{"title":"One trading cycle","kind":"practice","given":[["Fund","Rs.100 m"],["Bought","Sugar for Rs.95 m (cash kept Rs.5 m)"],["Sold","On 60-day credit for Rs.101 m"],["Manager’s Mudarabah share","20 % of profit"]],"working":["Profit = 101 − 95 = Rs.6 m; manager 1.2 m, investors 4.8 m.","After the credit sale the fund holds Rs.5 m cash and Rs.101 m receivables, with no goods.","While it holds mainly cash and debts, units can trade only at face value (debt and Sarf rules), until new goods are bought."],"answer":"Investors Rs.4.8 m; units stop being freely tradable while the fund is all cash and receivables."},"controls":["The fund may not sell goods it does not yet own and possess.","No speculative futures; Salam requires advance payment and actual delivery (p. 206).","Tradability follows the dominant asset class (p. 205)."],"risks":[["Commodity price falls","Borne by investors; diversified commodities"],["Credit sale default","Security and limits"]],"conventional":{"name":"Commodity futures fund","diff":["Conventional: futures without delivery. Islamic: real goods bought, possessed and sold."]},"origin":["f1"]},{"id":"murabaha-fund","name":"Murabaha funds (closed-end)","category":"Funds & investment banking","who":["inv"],"use":["save"],"need":"Investors want a stable return from a pool of Murabaha sales.","contracts":["islamic-funds","murabaha","bai-dayn"],"modeIds":["murabaha"],"topicIds":["t8.8.1","t15.3.5.c"],"how":["Subscriptions finance Murabaha sales of goods to buyers on deferred payment.","Once the goods are sold, the portfolio is Murabaha receivables, which are debts.","So a Murabaha fund should be closed-end: its units cannot be traded in a secondary market (p. 201).","Murabaha funds can also issue Murabaha Sukuk for sales of pre-specified assets, giving a quasi-fixed return (p. 406)."],"numerical":{"title":"Why units cannot trade above face value","kind":"practice","given":[["Units issued","Rs.50 m"],["Murabaha receivables","Rs.54 m (cost 50 m + profit 4 m, due in 9 months)"],["An investor wants to sell units after 3 months","Price offered Rs.52 m"]],"working":["The units now represent Rs.54 m of debt.","Selling debt for a different amount of money is Riba; transfer is possible only at face value, under Hawalah rules.","So a secondary market at 52 m (or any market price) is not allowed; the investor waits to maturity."],"answer":"No secondary trading at a market price; the fund is closed-end and holders are paid at maturity."},"controls":["Closed-end; no negotiable units (p. 201).","Each Murabaha: ownership and possession before sale.","No increase in the receivable for late payment."],"risks":[["Buyer default","Security; diversified buyers"],["Illiquidity for investors","Closed-end term matched to Murabaha tenors"]],"conventional":{"name":"Money-market or trade-receivables fund","diff":["Conventional: tradable debt at discount. Murabaha fund: receivables cannot be sold at a discount."]},"origin":["f1"]},{"id":"mixed-fund","name":"Mixed (balanced) funds","category":"Funds & investment banking","who":["inv"],"use":["save"],"need":"Investors want one fund holding shares, leases, commodities and receivables.","contracts":["islamic-funds","sukuk","ijarah","murabaha","screening"],"modeIds":["sukuk","ijarah","murabaha"],"topicIds":["t8.8.1","t8.8.4","t15.3.6"],"how":["Subscriptions go into different investments: equities, leasing, commodities, etc. (p. 201).","For units to trade, tangible assets should exceed 51 %, with liquid assets and debts under 50 % (Usmani).","Instruments representing a pool follow the dominant category: if cash and debts dominate, Sarf rules apply; if real assets dominate, market price (p. 205).","Where receivables are held, the unit price cannot fall below the value of those debts (p. 374)."],"numerical":{"title":"Tradability test and minimum price","kind":"practice","given":[["Shares and leased assets","Rs.60 m"],["Cash","Rs.15 m"],["Murabaha receivables","Rs.25 m"],["Units in issue","10 m"]],"working":["Tangible share = 60 ÷ 100 = 60 % > 51 % → units may trade at a market price.","Minimum price: the units carry Rs.40 m of cash and debts, so the price for all units should exceed Rs.40 m, i.e. above Rs.4.00 per unit.","If receivables rose to Rs.50 m (tangibles 35 %), trading would follow the rules for money and debt."],"answer":"Tradable (60 % tangible); price must exceed Rs.4.00 per unit."},"controls":["Keep tangibles above the threshold at all times.","Screen equities; exclude interest-bearing securities.","Price floor: more than the liquid assets and debts in the pool (p. 400)."],"risks":[["Drift below the tangible threshold","Continuous monitoring; rebalancing"],["Mixed risk profile","Disclosure of asset mix"]],"conventional":{"name":"Balanced fund","diff":["Conventional: shares plus bonds. Islamic: shares plus leases, commodities and limited receivables, with tradability rules."]},"calcId":"sukuk-trade","origin":["f1"]},{"id":"mudarabah-sukuk","name":"Mudarabah (Muqaradah) Sukuk","category":"Sukuk","who":["corp","inv"],"use":["raise","save"],"need":"Raise funds for a project that the issuer will manage, with investors sharing the profit.","contracts":["mudarabah","sukuk"],"modeIds":["mudarabah","sukuk"],"topicIds":["t15.3.5","t12.4"],"how":["The issuer is the Mudarib; subscribers own the capital and the Mudarabah’s assets (p. 398).","The prospectus gives all the Qirad terms: capital, profit ratio and conditions (OIC Fiqh Council, 1988).","Holders get the agreed share of actual profit, bear any loss, and have no management rights (Box 8.3).","The manager may invest its own funds and earn on them as a partner. A reserve can be built from profits, and an unrelated third party may promise a donation towards losses."],"numerical":{"title":"Profit and a reserve on Mudarabah Sukuk","kind":"practice","given":[["Sukuk issued","Rs.1,000 m"],["Project profit for the year","Rs.150 m"],["Profit ratio (holders : Mudarib)","70 : 30"],["Reserve for contingencies","5 % of profit, deducted first"]],"working":["Reserve = 150 × 5 % = Rs.7.5 m; distributable = Rs.142.5 m.","Holders = 142.5 × 70 % = Rs.99.75 m (9.975 %); Mudarib Rs.42.75 m.","The issuer cannot guarantee the capital or a fixed profit."],"answer":"Holders Rs.99.75 m (≈ 10 %), Mudarib Rs.42.75 m, reserve Rs.7.5 m."},"controls":["No capital or fixed-profit guarantee by the issuer or manager (p. 399).","Trading: at par while money (Sarf); by debt rules while receivables; at market price once assets are mixed.","The P&L of the project is published to holders."],"risks":[["Project loss","Borne by holders; reserves; third-party donation promise"],["Mudarib misconduct","Liability for negligence and breach"]],"conventional":{"name":"Revenue bond / profit-participating note","diff":["Conventional notes promise coupons. Mudarabah Sukuk pay only actual profit, and holders bear losses."]},"diagramId":"mudarabah-sukuk","calcId":"sukuk-trade","caseIds":["c-mudarabah-sukuk-trade"],"origin":["f1"]},{"id":"musharakah-sukuk","name":"Musharakah Sukuk and participation certificates (e.g. Sudan’s GMCs/CMCs)","category":"Sukuk","who":["corp","inv"],"use":["raise","save"],"need":"Mobilise large amounts for a project, with the manager also investing and sharing loss.","contracts":["musharakah","sukuk","shirkah"],"modeIds":["musharakah","sukuk"],"topicIds":["t15.3.5","t12.7.3","t8.8.3"],"how":["Each certificate represents proportionate ownership of the project’s assets; holders are partners with control and management rights (Box 8.3).","The manager also contributes capital, giving holders a cushion and sharing both profit and loss (p. 400).","Certificates become negotiable after the project starts and non-liquid assets exceed 50 %.","Sudan issued central bank and government Musharakah certificates (CMCs and GMCs) from 1998, in place of T-bills, for open-market operations."],"numerical":{"title":"Manager’s participation as a cushion","kind":"practice","given":[["Holders’ capital","Rs.900 m"],["Manager’s capital","Rs.100 m"],["Profit ratio (holders : manager)","80 : 20"],["Result","Loss of Rs.50 m"]],"working":["Loss follows capital: holders 90 % = Rs.45 m; manager 10 % = Rs.5 m.","With a profit of Rs.120 m instead: holders Rs.96 m, manager Rs.24 m.","Unlike a pure Mudarib, the manager shares the loss on its own capital."],"answer":"Loss: holders Rs.45 m, manager Rs.5 m. Profit of 120 m: 96 m / 24 m."},"controls":["Trading only when non-liquid assets exceed 50 %; the price must exceed the liquid assets (p. 400).","No guarantee of capital by the manager.","Loss strictly by capital."],"risks":[["Project underperforms","Manager’s own capital; monitoring rights"],["Illiquid secondary market","Listing; central bank auctions (Sudan)"]],"conventional":{"name":"Treasury bills / corporate bonds","diff":["Conventional: fixed interest. Musharakah Sukuk: ownership with variable profit and shared loss."]},"diagramId":"securitisation","calcId":"sukuk-trade","caseIds":["c-sitara"],"origin":["f1"]},{"id":"salam-sukuk","name":"Salam Sukuk (e.g. Bahrain’s aluminium Salam securities)","category":"Sukuk","who":["corp","bank"],"use":["raise","cash"],"need":"A government or producer wants funds now against a commodity it will deliver later; banks want short-term liquid assets.","contracts":["salam","wakalah","sukuk"],"modeIds":["salam","wakalah","sukuk"],"topicIds":["t15.3.5.c","t10.10","t8.8.3"],"how":["Holders pay the Salam price in advance; the seller issues the certificates and delivers the commodity later (p. 403).","BMA (June 2001): the Bahrain government sells aluminium on Salam to Bahrain Islamic Bank, representing the participating banks, for three-month tenors used for liquidity (SLR) requirements.","BIB appoints the government its agent to market the aluminium on delivery at a price giving holders their return.","Box 8.3: short-term and non-tradable, because the certificates represent a Salam debt."],"numerical":{"title":"Return on a three-month Salam issue","kind":"practice","given":[["Salam price paid","US$25 m for aluminium delivered in 3 months"],["Agent’s expected sale price","US$25.35 m"],["Agent’s fee","Nil (government acts as agent)"]],"working":["Gross return = 25.35 − 25 = US$0.35 m.","Annualised = 0.35 ÷ 25 × 12/3 = 5.6 % p.a.","If aluminium sells for less, holders earn less: the return depends on a real sale."],"answer":"US$0.35 m, about 5.6 % p.a., if the aluminium sells at US$25.35 m."},"controls":["Full price paid in advance; commodity specified in kind, quality and quantity.","No secondary trading while the certificate is a Salam debt (p. 404).","The agency to sell is separate from the Salam contract."],"risks":[["Commodity price falls at delivery","Liquid, heavily traded commodities; agency marketing"],["Seller fails to deliver","Sovereign seller; security"]],"conventional":{"name":"Short-term treasury bills","diff":["T-bills pay interest. Salam Sukuk earn the margin on a real commodity sale and cannot be traded before delivery."]},"diagramId":"salam-sukuk","calcId":"salam-profit","origin":["f1"]},{"id":"istisna-sukuk","name":"Istisna‘a Sukuk","category":"Sukuk","who":["corp"],"use":["raise","project"],"need":"Fund the manufacture or construction of an asset, with investors paid from its deferred price.","contracts":["istisna","sukuk","bai-dayn"],"modeIds":["istisnaa","sukuk"],"topicIds":["t15.3.5.c","t10.11.7","t8.8.3"],"how":["The manufacturer (seller) issues certificates; holders are the buyers of the item to be produced (p. 404).","Funds pay a contractor, often through Parallel Istisna‘a; on delivery, the ultimate buyer owes a deferred price that includes profit.","While the funds are converted into assets owned by holders during manufacture, the certificates may be traded.","Once the price is a debt owed by the ultimate buyer, they can be transferred only at face value; there is no secondary market at a discount (p. 405)."],"numerical":{"title":"Face-value transfer after delivery","kind":"practice","given":[["Certificates","Rs.1,000 m, repaid Rs.250 m a year for 5 years (total Rs.1,250 m)"],["After delivery","The buyer owes Rs.1,250 m"],["An investor wants cash after year 2","Remaining claim Rs.750 m"]],"working":["The claim is a debt of Rs.750 m.","It can be transferred to a third party only at Rs.750 m (face value).","Alternatively, the holder may take goods at the seller’s deferred price, which is higher than spot, so market forces still play a role (p. 405)."],"answer":"Transferable only at Rs.750 m face value; no discounting."},"controls":["Price and specification fixed in the Istisna‘a.","No sale of the debt at other than face value.","The two Istisna‘a contracts are independent."],"risks":[["Construction delay","Parallel Istisna‘a with penalties for delay"],["Illiquid for investors","Serial maturities matching payment dates"]],"conventional":{"name":"Project bond","diff":["Project bonds trade at market yields. Istisna‘a Sukuk are debts after delivery and move only at face value."]},"diagramId":"parallel-istisna","calcId":"parallel-istisna","origin":["f1"]},{"id":"murabaha-sukuk","name":"Murabaha Sukuk (e.g. Arcapita 2005)","category":"Sukuk","who":["corp"],"use":["raise","asset"],"need":"A buyer, often a government, pays for costly goods in instalments; or a Murabaha fund raises money.","contracts":["murabaha","sukuk","bai-dayn","hawalah"],"modeIds":["murabaha","sukuk","hawalah"],"topicIds":["t15.3.5.c","t15.3.6"],"how":["A government buys goods on credit and issues a certificate for each instalment, each representing the seller’s claim (p. 405).","The claim can change hands only without changing its amount; collection rights can be transferred at face value, less collection cost.","Murabaha receivables alone cannot create negotiable Sukuk; a mixed pool with over 50 % Ijarah or fixed assets can (over 10 % on the Hanafi view).","Arcapita (Bahrain) issued five-year multicurrency Sukuk in 2005 for commodity Murabaha, paying 3-month LIBOR + 175 bps; their tradability rests on the SPV holding enough inventory or fixed assets (p. 406)."],"numerical":{"title":"Instalment certificates for a government purchase","kind":"practice","given":[["Goods cost","Rs.4,000 m"],["Murabaha profit","15 % for the whole period"],["Payment","5 equal annual instalments, one certificate each"]],"working":["Price = 4,000 × 1.15 = Rs.4,600 m.","Each certificate = 4,600 ÷ 5 = Rs.920 m, payable on its maturity date.","A holder can transfer a certificate only for Rs.920 m, less any collection cost."],"answer":"Five certificates of Rs.920 m, transferable at face value only."},"controls":["No discounting of Murabaha receivables (p. 405).","Trading allowed only if the pool is dominated by real assets.","Commodity Murabaha must involve real ownership and possession."],"risks":[["Buyer default","Sovereign or bank recourse (Arcapita)"],["Paper-only commodity trades","Shari’ah board approval of the mechanism"]],"conventional":{"name":"Government instalment bonds","diff":["Bonds trade at a discount. Murabaha Sukuk carry a fixed debt that cannot be sold below face value."]},"origin":["f1"]},{"id":"mixed-portfolio-sukuk","name":"Mixed-portfolio Sukuk (IDB Solidarity Trust, 2003)","category":"Sukuk","who":["bank","corp"],"use":["raise","cash"],"need":"A bank or DFI turns a mix of illiquid Ijarah, Murabaha and Istisna‘a assets into tradable certificates.","contracts":["sukuk","ijarah","murabaha","istisna","wakalah"],"modeIds":["sukuk","ijarah","murabaha","istisnaa","wakalah"],"topicIds":["t15.3.5.d","t15.3.6"],"how":["IDB originated a portfolio of Ijarah, Murabaha and Istisna‘a contracts; ICD bought it and sold it to the SPV, Solidarity Trust Services (Figure 15.2).","US$400 m trust certificates each represent undivided beneficial ownership, ranking pari passu.","Over 50 % must always be Ijarah; if Ijarah falls below 25 %, dissolution occurs and IDB must buy the assets under a purchase undertaking.","ICD acts as Wakil; IDB guarantees the obligors’ scheduled payments and provides an interest-free facility for timely distributions; principal is reinvested in Ijarah and Musharakah."],"numerical":{"title":"Monitoring the Ijarah share","kind":"practice","given":[["Ijarah assets","US$230 m"],["Murabaha receivables","US$120 m"],["Istisna‘a receivables","US$50 m"]],"working":["Ijarah share = 230 ÷ 400 = 57.5 % > 50 % ✓ — the certificates stay tradable.","If Ijarah fell to US$180 m (45 %), the pool would breach the requirement that over 50 % be Ijarah at all times.","Below 25 % (under US$100 m), a dissolution event triggers IDB’s purchase undertaking."],"answer":"57.5 % Ijarah: compliant; the thresholds are 50 % (tradability) and 25 % (dissolution)."},"controls":["Ijarah majority maintained at all times (p. 406).","Guarantee covers the obligors’ scheduled payments, not the certificates’ return as such.","Reinvestment of principal only in Ijarah and Musharakah."],"risks":[["Ijarah share falls","Reinvestment; dissolution trigger"],["Obligor default","IDB guarantee and liquidity facility"]],"conventional":{"name":"Collateralised loan / asset-backed security","diff":["ABS pools debts and trades them at a discount. Mixed Sukuk trade only because real Ijarah assets dominate the pool."]},"diagramId":"idb-sukuk","calcId":"sukuk-trade","caseIds":["c-idb"],"origin":["f1"]},{"id":"usufruct-sukuk","name":"Sukuk of usufruct and services (e.g. education)","category":"Sukuk","who":["corp"],"use":["raise"],"need":"Pre-sell the use of an asset or future services (e.g. university places) to raise funds now.","contracts":["ijarah","sukuk"],"modeIds":["ijarah","sukuk"],"topicIds":["t15.3.5.b","t15.3.4"],"how":["AAOIFI’s Ijarah Sukuk include ownership of the usufruct of existing assets and of described future assets, and of services from a specified supplier or described future services (pp. 401–402).","Subscription money is the price of the usufruct or services; holders own them, with risks and rewards.","Usufruct certificates may be traded before sub-leasing; once sub-leased, they represent rent receivables and follow debt rules.","Future-usufruct Sukuk can trade only after the asset is identified."],"numerical":{"title":"Education services Sukuk","kind":"practice","given":[["Sukuk sold","Rs.300 m for 1,000 four-year degree places"],["Places sub-sold to students","Rs.360,000 each"],["Holders’ cost per place","Rs.300,000"]],"working":["Sub-sale proceeds = 1,000 × 360,000 = Rs.360 m.","Holders’ gross gain = 360 − 300 = Rs.60 m (20 % over four years).","Before the places are sub-sold, holders own services and may trade the Sukuk; afterwards they hold receivables, at face value only."],"answer":"Rs.60 m gross gain; tradable only until the services are sub-sold."},"controls":["Services or usufruct precisely described.","Trading rules change once the usufruct is sub-leased (receivables).","The issuer may redeem at market price or an agreed price after subscription."],"risks":[["Supplier fails to provide the service","Specified supplier; performance security"],["Places not taken up","Holders bear the risk as owners"]],"conventional":{"name":"Pre-sale revenue bonds","diff":["Conventional: a loan repaid from fees. Usufruct Sukuk: holders own the service itself."]},"calcId":"sukuk-trade","origin":["f1"]}]);
